window.DBD_DATA.perks.push(...[{"id":"appraisal","rank":145,"tier":"C","roles":["Item","Objective"],"summary":"Start with four Tokens and rummage opened Chests for extra Items up to four times, at greatly increased rummage speed.","metaStatus":"Situational","skillLevel":"Low","soloQ":2,"swf":2,"unlockPriority":"Low–Medium","glossaryKeys":[],"useCases":["Turn already-opened Chests into additional Items.","Feed chest-based perks that care about repeated searches or Item supply.","Create more team resources without bringing four Items from the lobby."],"counters":["Chest routing costs objective time.","The extra Item is still random.","Four Tokens cap the total value."],"pros":["Four extra Item rolls is substantial resource volume.","Up to 80% faster rummaging reduces the side-objective tax.","Each Chest can support two rummages."],"cons":["Random loot quality.","Chest-dependent.","Often weaker than bringing the desired Item directly."],"analysis":["Appraisal is a resource-generation perk rather than a direct match-speed perk. Four Tokens means four additional Item rolls from Chests that were already opened, which can create a surprising amount of total equipment.","The 80% rummage-speed bonus makes the interaction less painful, and modern chest builds can combine Appraisal with Plunderer’s Instinct, Pharmacy, Ace in the Hole, or Moment of Glory.","The opportunity cost remains travel and randomness. A Survivor who crosses the map to rummage for an Item they never needed may lose more generator time than the resource can repay.","Appraisal is therefore a legitimate chest-build engine and a poor blind general slot. Its ranking should be judged alongside the entire loot package rather than in isolation."],"verdict":"The engine room of chest builds: lots of extra Items, little certainty that those Items were worth the detour.","publicationStatus":"published","tags":["Chest","Resource"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Élodie Rakoto"},"synergyPerkIds":["plunderers-instinct","pharmacy","ace-in-the-hole","moment-of-glory"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Plunderer's Instinct","Pharmacy","Ace in the Hole","Moment of Glory"],"antiSynergies":[],"name":"Appraisal","alternateName":null,"source":"Élodie Rakoto","status":"Live 10.2.0","currentEffect":"Start the Trial with 4 Tokens. Rummaging through an already opened Chest consumes 1 Token and retrieves an additional Item. Each Chest can be rummaged up to twice. You rummage 40/60/80% faster.","activation":["Have a Token and rummage through an already opened Chest.","Ends/deactivates when: Cannot be used after all Tokens are spent."],"patchNote":"Latest live balance change (9.1.0): Updated Appraisal to allow two rummages per Chest and added tiered rummage-speed values.","plainEnglishSummary":"Spend up to four tokens to retrieve extra Items from already opened Chests.","cooldown":null,"duration":[],"tokenOrStackBehavior":"Starts with 4 Tokens; each rummage consumes 1; maximum two rummages per Chest.","oncePerTrialOrOtherLimits":"Maximum four rummages per Trial.","statusEffectsInvolved":[],"specialInteractions":["A Chest must already have been opened."],"sourceCharacter":"Élodie Rakoto","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"clairvoyance","rank":146,"tier":"C","roles":["Information","Totem"],"summary":"After cleansing or blessing a Totem, while empty-handed you can reveal chests, gates, generators, Hatch, and hooks within 64 metres for up to 12 seconds.","metaStatus":"Situational","skillLevel":"Low–Medium","soloQ":3,"swf":2,"unlockPriority":"Medium","glossaryKeys":["aura-reading"],"useCases":["Locate the Hatch or Exit Gate switches in late-game situations.","Scout hooks, generators, and chests after a Totem interaction.","Use the information burst to plan a long rotation without carrying an Item."],"counters":["Requires a prior Totem cleanse or blessing.","You must be empty-handed to use it.","The total Aura-reading time is limited."],"pros":["Very broad object list.","Sixty-four-metre radius.","Includes Hatch information."],"cons":["Setup plus empty-hand restriction.","No Killer or teammate information.","Limited duration."],"analysis":["Clairvoyance ranks this position because its object list is broad enough to solve several navigation problems at once. The Hatch inclusion is especially notable, giving the perk a potential endgame purpose beyond ordinary generator routing.","The Totem setup is not terrible in builds already cleansing or blessing, but it is still a requirement. The empty-hand condition can also conflict with strong Items, making the perk less attractive in equipment-heavy builds.","The twelve seconds of total use should be treated as a scouting resource rather than a permanent map overlay. A short scan can identify the direction of gates, generators, hooks, or the Hatch before you resume normal movement.","It remains lower B because the information is about objects rather than threats. Useful navigation is nice, but the strongest perks tell you where the Killer is or directly change survival odds."],"verdict":"A flexible object scanner with useful Hatch information. Clairvoyance solves navigation problems, but its setup and empty-hand requirement keep it niche.","publicationStatus":"published","tags":["Scouting"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Mikaela Reid"},"synergyPerkIds":["detective-s-hunch","inner-strength","counterforce","left-behind"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Detective's Hunch","Inner Strength","Counterforce","Left Behind"],"antiSynergies":[],"name":"Clairvoyance","alternateName":null,"source":"Mikaela Reid","status":"Live 10.2.0","currentEffect":"After cleansing or blessing a Totem, while empty-handed hold the Use Item button to reveal Auras of Chests, Exit Gate switches, Generators, the Hatch, and Hooks within 64 metres, for up to 10/11/12 seconds while the interaction is held.","activation":["Cleanse or bless a Totem.","Be empty-handed and hold Use Item.","Ends/deactivates when: Aura reading ends when the button is released or after 10/11/12 seconds."],"patchNote":"Latest live balance change (9.2.0): Increased maximum aura-reading duration to 10/11/12 seconds.","plainEnglishSummary":"After interacting with a Totem, you can reveal several important object Auras while empty-handed.","cooldown":null,"duration":["Aura-reading duration: up to 10/11/12 seconds by tier."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":["Reveals Chests, Exit Gate switches, Generators, Hatch and Hooks within 64 metres."],"sourceCharacter":"Mikaela Reid","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"last-stand","rank":147,"tier":"C","roles":["Chase","Utility"],"summary":"After spending 90 seconds inside the Killer's Terror Radius outside chase, your next close rushed vault can stun the Killer for 3 seconds, once per Trial.","metaStatus":"Situational","skillLevel":"High","soloQ":2,"swf":3,"unlockPriority":"Medium","glossaryKeys":["terror-radius","looping"],"useCases":["Cash the charged perk during a critical close vault to force a three-second chase swing.","Use against a Killer who repeatedly patrols near you without committing to chase.","Pair with vault-heavy chase builds so the one-use stun arrives at a meaningful moment."],"counters":["Ninety seconds of Terror Radius time outside chase is an enormous setup requirement.","The Killer must be within 2.5 metres of the rushed vault.","The perk disables permanently after its one successful trigger."],"pros":["Three-second Killer stun is a large payoff.","Can surprise the Killer at a normally unsafe close vault.","Current usage shows players do build intentionally around it."],"cons":["One-use only.","Extremely slow setup.","Stealth Killers can make charging much harder."],"analysis":["Last Stand ranks this position because a three-second stun from an ordinary rushed vault can absolutely win a chase interaction. The effect itself is not weak; the ninety-second charging requirement is what drags the perk down.","That charging time must occur inside the Terror Radius while you are not in chase. A match against a mobile or stealth Killer can make the condition painfully slow, while a territorial Killer may charge it more naturally around contested objectives.","Once ready, the perk still needs a close vault with the Killer inside 2.5 metres. Good timing can transform a near-hit into a stun and enough distance to reset the chase.","The payoff is fun and real, but a single-use perk with both a ninety-second setup and a positional trigger cannot rank on payoff alone."],"verdict":"A strong one-time stun buried under a marathon charging condition. Last Stand can steal a chase, but spends most of the Trial asking when the dramatic music starts.","publicationStatus":"published","tags":["Stun","Comeback"],"queueRatingStatus":"reviewed","rankRange":[138,156],"rankConfidence":"Low","rankStatus":"stable","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Michonne Grimes"},"synergyPerkIds":["finesse","lithe","teamwork-throw-down"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","rank-review-applied","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Finesse","Lithe","Teamwork: Throw Down"],"antiSynergies":[],"name":"Last Stand","alternateName":null,"source":"Michonne Grimes","status":"Live 10.2.0","currentEffect":"After you spend 120/105/90 seconds in the Killer's Terror Radius while not in a Chase, Last Stand activates. While active, a Rushed Vault stuns the Killer for 3 seconds if they are within 2.5 m of the vault location. After the perk triggers, it is disabled for the remainder of the Trial.","activation":["Accumulate 120/105/90 seconds in the Killer's Terror Radius while not in a Chase.","While active, perform a Rushed Vault with the Killer within 2.5 m of the vault location.","Ends/deactivates when: After its stun triggers, the perk is disabled for the remainder of the Trial."],"patchNote":"Latest live balance change (9.1.0): Introduced live with a 120/105/90-second Terror Radius charge requirement and a 3-second stun; the launch values were higher than the preceding PTB proposal.","plainEnglishSummary":"Time spent in the Terror Radius outside Chase charges a one-use stun that can trigger on a close Rushed Vault.","cooldown":null,"duration":["Killer stun: 3 seconds."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":"Once the effect triggers, it cannot be used again for the remainder of the Trial.","statusEffectsInvolved":[],"specialInteractions":[],"sourceCharacter":"Michonne Grimes","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"boon-dark-theory","rank":148,"tier":"C","roles":["Boon","Chase","Mobility"],"summary":"Create a 24-metre Boon zone that grants Survivors 3% Haste, lingering briefly after they leave the area.","metaStatus":"Situational","skillLevel":"Medium","soloQ":2,"swf":3,"unlockPriority":"Medium","glossaryKeys":["haste","looping"],"useCases":["Place the Boon near a strong connected chase area so multiple loops benefit from 3% Haste.","Stack the effect with other Boons on one Totem to lower the setup cost.","Use the short linger to carry the movement bonus into a transition out of the Boon radius."],"counters":["The Killer can snuff the Totem.","Three percent Haste is powerful only if the chase actually remains inside useful geometry.","Bad Totem placement can put the effect far away from every important chase."],"pros":["Teamwide Haste rather than owner-only value.","Three percent is enough to change some loop timings.","9.5/8.7-era version is stronger than its old 2% form."],"cons":["Map and Totem geometry determine most of the value.","Requires blessing time.","Snuffing erases the whole investment."],"analysis":["Boon: Dark Theory is useful only conditionally because 3% Haste is a real chase modifier, but the effect is trapped inside a twenty-four-metre circle. When that circle covers a strong building or several connected tiles, the Killer can feel the difference immediately.","The perk becomes more efficient in a multi-Boon loadout. Shadow Step, Circle of Healing, Steadfast, and Dark Theory can all share one Totem, so the blessing action buys several effects rather than paying a full setup tax for 3% movement alone.","The problem is geography. A Boon behind a dead-zone corner might be safe from snuffing and still accomplish nothing. A perfect central Boon may influence multiple chases but also be obvious enough for the Killer to remove.","Dark Theory therefore has a higher ceiling than many similarly ranked niche perks but a lower floor than general chase tools. It is a zone-control perk, and the zone has to matter."],"verdict":"A real team chase buff with a map-shaped reliability problem. Dark Theory can make a strong area stronger, but cannot guarantee the match happens inside its circle.","publicationStatus":"published","tags":["Haste"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Yoichi Asakawa"},"synergyPerkIds":["boon-shadow-step","boon-circle-of-healing","boon-steadfast","hope"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Boon: Shadow Step","Boon: Circle of Healing","Boon: Steadfast","Hope"],"antiSynergies":[],"name":"Boon: Dark Theory","alternateName":null,"source":"Yoichi Asakawa","status":"Live 10.2.0","currentEffect":"Bless a Dull or Hex Totem. Survivors within 24 metres gain 3% Haste; the effect lingers for 2/3/4 seconds after leaving its range.","activation":["Bless a Dull or Hex Totem.","Be within 24 metres for the main Haste effect.","Ends/deactivates when: Effect ends after leaving range and the tiered linger time, or when the totem is snuffed."],"patchNote":"Latest live balance change (8.7.0): Increased Haste from 2% to 3%.","plainEnglishSummary":"A Boon Totem grants nearby Survivors 3% Haste that briefly persists after leaving its radius.","cooldown":null,"duration":["Haste lingers 2/3/4 seconds outside the Boon range."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":"One active Boon Totem per Survivor; equipped Boons apply to that totem.","statusEffectsInvolved":["Haste"],"specialInteractions":[],"sourceCharacter":"Yoichi Asakawa","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"fruits-of-your-labor","rank":149,"tier":"C","roles":["Objective","Healing","Mobility"],"summary":"Generator completions build Tokens; when you finish repairing a generator, each Token grants a brief Haste bonus and permanent healing progress toward your current Health State.","metaStatus":"Situational","skillLevel":"Low–Medium","soloQ":2,"swf":2,"unlockPriority":"Medium","glossaryKeys":["haste","health-state","pressure"],"useCases":["Convert late generator completions into a large chunk of healing progress.","Finish a generator while injured and immediately gain movement plus self-recovery progress.","Benefit more in later game when several completion Tokens have accumulated."],"counters":["You must personally finish a generator to cash the Tokens.","Early-game activations have few Tokens and modest payoff.","If you are already Healthy, the healing portion can be wasted."],"pros":["Rewards the main objective rather than a side quest.","Scaling improves naturally as the Trial progresses.","Can combine objective completion, healing progress, and movement in one trigger."],"cons":["Back-loaded value.","Needs the perk owner to be on the exact generator when it completes.","Part of the trigger is wasted in some health states."],"analysis":["Fruits of Your Labor ranks high in C because the perk scales with match progression rather than requiring an unrelated chore. Every generator completion creates future value, and the payout happens when you personally finish a generator later.","The healing progress is the more interesting reward. If several Tokens are banked and you finish a late generator while injured, the perk can remove a large portion of the next heal without requiring anyone to stop repairing beforehand.","The brief Haste can help with the immediate post-completion rotation, but it is not a replacement for a true Exhaustion perk. The important question is whether you can reliably be present for the generator finish that cashes the stack.","That ownership problem keeps the perk in C. Solo Q teammates may finish objectives without you, and an early finish pays very little. In a coordinated objective build, the scaling can be planned much more deliberately."],"verdict":"A promising late-objective payoff that asks you to own the generator finish. Fruits of Your Labor can compress a later heal nicely, but its value arrives on the match's schedule.","publicationStatus":"published","tags":["Haste"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Aurora Stardotter"},"synergyPerkIds":["resilience","deja-vu","adrenaline","hope"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Resilience","Déjà Vu","Adrenaline","Hope"],"antiSynergies":[],"name":"Fruits of Your Labor","alternateName":null,"source":"Aurora Stardotter","status":"Live 10.2.0","currentEffect":"Whenever a Generator is completed, you gain 1 Token. Whenever you finish repairing a Generator, for each Token you gain 5% Haste for 2 seconds and 10/15/20% Healing progress, according to perk tier.","activation":["Whenever any Generator is completed, gain 1 Token.","You must finish repairing a Generator to trigger the per-Token Haste and Healing progress.","Ends/deactivates when: Each Haste instance lasts 2 seconds."],"patchNote":"Latest live balance change (unknown): No material live balance change could be verified from available patch history.","plainEnglishSummary":"Generator completions build tokens that grant a brief Haste boost and Healing progress when you finish repairing a Generator.","cooldown":null,"duration":["Haste: 2 seconds per Token when you finish repairing a Generator."],"tokenOrStackBehavior":"Gain 1 Token whenever any Generator is completed. No cap, token expenditure, loss, or expiry is stated in the current effect text; tokens remain available for each time you finish repairing a Generator.","oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":["Haste"],"specialInteractions":["The per-Token Haste and Healing progress occur when you finish repairing a Generator, not merely when another Generator is completed."],"sourceCharacter":"Aurora Stardotter","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"bardic-inspiration","rank":150,"tier":"C","roles":["Skill Check","Team Support","Objective"],"summary":"Perform for up to 15 seconds, roll a d20, and give nearby Survivors 90 seconds of bonus progress on successful basic Skill Checks.","metaStatus":"Situational","skillLevel":"Medium","soloQ":1,"swf":3,"unlockPriority":"Medium","glossaryKeys":["swf","pressure"],"useCases":["Buff a coordinated group before a generator push.","Pair with Hyperfocus or other Skill Check-heavy builds that create many chances to use the bonus.","Use the Aura shown during the performance to gather teammates intentionally."],"counters":["The performance itself consumes up to 15 seconds of productive time.","The d20 result is random and can produce only a small bonus or even a scream with no benefit.","Long cooldown prevents frequent retrying."],"pros":["Can affect multiple Survivors for 90 seconds.","Skill Check progress bonuses can add up in high-frequency builds.","Fun team utility with a real ceiling on high rolls."],"cons":["Large setup cost.","Random outcome.","Much weaker when teammates do not generate many Skill Checks."],"analysis":["Bardic Inspiration can create legitimate team objective value, but it begins by asking one Survivor to stop productive actions for as long as fifteen seconds before the d20 result is known.","A strong result lasts ninety seconds and can reward many basic Skill Checks across several Survivors. Hyperfocus and ONE-TWO-THREE-FOUR! are natural ways to build around frequent Skill Checks without relying on the obsolete Stake Out interaction.","The randomness is the ranking anchor. A poor roll produces too little payoff for the setup, while the worst result can turn the performance into a scream and no mechanical benefit.","Coordinated teams get the cleanest version because they can group briefly, receive the buff, then split. In normal queues, the perk remains much less dependable."],"verdict":"A genuine team Skill Check buff wrapped in a fifteen-second dice roll. Bardic Inspiration can pay off handsomely, but the setup and RNG keep it comfortably out of the reliable tiers.","publicationStatus":"published","tags":["Team"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Aestri Yazar"},"synergyPerkIds":["hyperfocus","one-two-three-four","prove-thyself"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Hyperfocus","One-Two-Three-Four!","Prove Thyself"],"antiSynergies":[],"name":"Bardic Inspiration","alternateName":null,"source":"Aestri Yazar","status":"Live 10.2.0","currentEffect":"Stand still and use the Active Ability button to begin a Performance that lasts up to 15 seconds and affects Survivors within 16 metres. At its end, roll a d20: 1 makes you scream without a Killer notification; 2–10 gives Skill Checks +1% progress; 11–19 gives +2%; 20 gives +3%. The result lasts 90 seconds. Cooldown is 110/100/90 seconds after the Performance ends or is cancelled.","activation":["Stand still and use the Active Ability button.","Other Survivors must be within 16 metres to be affected.","Ends/deactivates when: Performance ends after at most 15 seconds or if cancelled; rolled effect lasts 90 seconds."],"patchNote":"Latest live balance change (unknown): No material live balance change could be verified from available patch history.","plainEnglishSummary":"A short Performance gives nearby teammates a random Skill Check bonus for 90 seconds.","cooldown":"110/100/90 seconds by tier","duration":["Performance: up to 15 seconds.","Rolled effect: 90 seconds."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":["Roll of 1 causes a scream without a Killer notification."],"sourceCharacter":"Aestri Yazar","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"lend-a-hand","rank":151,"tier":"C","roles":["Healing","Totem","Objective"],"summary":"After cleansing or blessing a Totem, add up to four permanent healing charges to a teammate while healing them, once per recipient.","metaStatus":"Situational","skillLevel":"Medium","soloQ":2,"swf":2,"unlockPriority":"Medium","glossaryKeys":["health-state","reset"],"useCases":["Turn a useful Totem interaction into permanent healing progress for a teammate.","Pre-load a teammate's health bar so a later heal needs less time.","Repeat the effect on different teammates if you fulfill the Totem condition again."],"counters":["Requires a Totem interaction before every new activation cycle.","Only four charges at Tier III, a fraction of one full heal.","Cannot repeatedly target the same recipient."],"pros":["Permanent charges do not decay.","Can be used multiple times in one Trial after new Totem interactions.","Pairs naturally with builds already touching Totems."],"cons":["Side-objective setup.","Modest individual payout.","Recipient restriction limits repeated optimization."],"analysis":["Lend a Hand lands at this position because permanent healing charges are mechanically valuable, but the four-charge payout is not large enough to justify chasing Totems solely for the perk. Its best use is piggybacking on a cleanse or Boon you already wanted.","Permanent progress is the important word. Once granted, the teammate's health state effectively has less work remaining for a future heal, and normal interruptions do not erase that stored reduction.","The perk can activate again after another Totem interaction, which creates a route toward helping multiple teammates across the Trial. Counterforce or a Boon build can make those activations far less awkward.","It stays in C because the economy is modest. The Totem time, travel, and healing setup often cost more than four charges are worth unless those actions were already part of the plan."],"verdict":"A nice bonus attached to Totem play, not a reason to become a Totem archaeologist. Lend a Hand is efficient when the setup was already useful.","publicationStatus":"published","tags":["Permanent Progress"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Shane Wiigwaas"},"synergyPerkIds":["counterforce","botany-knowledge","empathy"],"synergyOther":["Boon perks"],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Counterforce","Botany Knowledge","Empathy","Boon perks"],"antiSynergies":[],"name":"Lend a Hand","alternateName":null,"source":"Shane Wiigwaas","status":"Live 10.2.0","currentEffect":"After you bless or cleanse 1 Totem, while healing another Survivor, press Activate Ability 2 to give that Survivor 2/3/4 permanent healing charges. The effect can be used multiple times in one Trial if you fulfill the Totem condition again, but only once per recipient.","activation":["Bless or cleanse 1 Totem to fulfill the activation condition.","While healing another Survivor, press Activate Ability 2.","Ends/deactivates when: The effect cannot be applied to the same recipient more than once by this perk user."],"patchNote":"Latest live balance change (10.0.1): Changed from once per match to reusable multiple times when the Totem condition is fulfilled again, while retaining a once-per-recipient limit.","plainEnglishSummary":"After a Totem interaction, you can add permanent healing charges to a teammate while healing them.","cooldown":null,"duration":["Healing charges given to the recipient are permanent."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":"Can be used multiple times per Trial after meeting the Totem condition again; only once per other Survivor.","statusEffectsInvolved":[],"specialInteractions":[],"sourceCharacter":"Shane Wiigwaas","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"duty-of-care","rank":152,"tier":"C","roles":["Team Support","Mobility"],"summary":"While Healthy, taking a Protection Hit gives every other Survivor within 12 metres 25% Haste for up to 6 seconds.","metaStatus":"Situational","skillLevel":"High","soloQ":1,"swf":3,"unlockPriority":"Medium","glossaryKeys":["haste","protection-hit","bodyblock","swf"],"useCases":["Bodyblock for an injured teammate and give them a major escape burst at the same time.","Use near hooks or carry saves where several Survivors are clustered.","Coordinate the trigger so the protected teammate reaches a safe tile immediately."],"counters":["You must be Healthy and take a Protection Hit.","Only other Survivors receive the Haste.","The twelve-metre radius is tight, so teammates may be outside the effect when the hit lands."],"pros":["25% Haste is a very large burst.","Can affect several teammates simultaneously.","Naturally supports protection-hit strategies."],"cons":["Requires deliberate risk to activate.","Short duration and small radius.","Can feed the Killer pressure if the bodyblock was unnecessary."],"analysis":["Duty of Care earns this position because twenty-five percent Haste for six seconds is not a small support effect. A successful protection hit can send an injured teammate flying toward safety while the perk owner absorbs the Killer's attack.","The challenge is arranging the geometry. The protected teammates must be within twelve metres at the moment the hit registers, and the perk owner must still be Healthy. A mistimed bodyblock can create two injured Survivors without producing a meaningful escape.","SWF gets much more from the perk because the team can call exactly when the protected Survivor needs the burst. Carry saves, hook trades, and coordinated bodyblocks all create predictable activation moments.","Duty of Care remains C because it requires the team to be clustered around danger, which is not always where Survivors should be. Its numerical ceiling is excellent; its opportunities are scarce."],"verdict":"A huge six-second movement gift attached to a risky Protection Hit. Duty of Care can rescue a teammate's chase, but only when the bodyblock is already the right play.","publicationStatus":"published","tags":["Protection Hit","Haste","Team"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Orela Rose"},"synergyPerkIds":["mettle-of-man","breakout","were-gonna-live-forever","background-player"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Mettle of Man","Breakout","We're Gonna Live Forever","Background Player"],"antiSynergies":[],"name":"Duty of Care","alternateName":null,"source":"Orela Rose","status":"Live 10.2.0","currentEffect":"While Healthy, taking a Protection Hit grants all other Survivors within 12 metres of you 25% Haste for 4/5/6 seconds.","activation":["Be Healthy when you take a Protection Hit.","Other Survivors must be within 12 metres of you.","Ends/deactivates when: Haste ends after 4/5/6 seconds."],"patchNote":"Latest live balance change (8.7.0): Introduced; no later material live balance change located in the official notes checked.","plainEnglishSummary":"Taking a Protection Hit while Healthy gives nearby teammates a short Haste effect.","cooldown":null,"duration":["Haste: 4/5/6 seconds by tier."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":["Haste"],"specialInteractions":["The perk owner is not included in the Haste effect; it applies to other Survivors within range."],"sourceCharacter":"Orela Rose","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"teamwork-throw-down","rank":153,"tier":"C","roles":["Team Support","Chase"],"summary":"Whenever you blind or pallet-stun the Killer, nearby injured teammates gain Endurance and see the Killer's Aura for up to 10 seconds.","metaStatus":"Situational","skillLevel":"High","soloQ":1,"swf":3,"unlockPriority":"Medium","glossaryKeys":["endurance","aura-reading","swf"],"useCases":["Protect an injured teammate during a coordinated pallet or blind save.","Turn a successful Killer stun into ten seconds where nearby teammates can absorb a hit without going down.","Use the Aura read to help the protected teammate choose an escape route."],"counters":["The perk does not protect the user.","Other Survivors must be injured and within 24 metres.","You must first successfully blind or pallet-stun the Killer."],"pros":["Ten seconds of Endurance can be decisive.","Includes Killer Aura information.","Excellent coordinated-save ceiling."],"cons":["Multiple conditions must overlap.","No value in ordinary solo chases with no teammate nearby.","High execution requirement."],"analysis":["Teamwork: Throw Down ranks this position because granting Endurance to another injured Survivor can completely change a save sequence. If a blind or pallet stun already bought the team time, ten protected seconds can prevent the Killer from immediately converting that teammate into another down.","The Killer Aura read helps the recipient use the protection intelligently rather than simply running blind. That is particularly valuable in cluttered rescue situations where several players are moving around the same structure.","The perk's floor is brutal. You need a successful blind or pallet stun, an injured teammate within twenty-four metres, and a game state where that teammate actually benefits from Endurance. Most ordinary chases will never satisfy all three.","This is therefore a SWF specialist with a high ceiling and low opportunity rate. In coordinated save squads it performs far above C; in standard matchmaking it can remain dormant for an entire Trial."],"verdict":"A powerful rescue-team effect hidden behind three simultaneous conditions. Throw Down is excellent when the whole play is coordinated and nearly blank when it is not.","publicationStatus":"published","tags":["Protection","Stun","Team"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Michonne Grimes"},"synergyPerkIds":["background-player","flashbang","head-on","champion-of-light"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Background Player","Flashbang","Head On","Champion of Light"],"antiSynergies":[],"name":"Teamwork: Throw Down","alternateName":null,"source":"Michonne Grimes","status":"Live 10.2.0","currentEffect":"Whenever you blind the Killer by any means or stun them with a Pallet, all other Injured Survivors within 24 m gain Endurance for 6/8/10 seconds.","activation":["Blind the Killer by any means or stun the Killer with a Pallet.","Other Survivors must be injured and within 24 m.","Ends/deactivates when: Endurance lasts 6/8/10 seconds, subject to Endurance rules."],"patchNote":"Latest live balance change (unknown): No material live balance change could be verified from available patch history.","plainEnglishSummary":"Blinding or Pallet-stunning the Killer grants nearby injured teammates Endurance.","cooldown":null,"duration":["Endurance: 6/8/10 seconds."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":["Endurance"],"specialInteractions":["The perk affects other injured Survivors in range, not the perk user."],"sourceCharacter":"Michonne Grimes","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"no-mither","rank":154,"tier":"C","roles":["Anti-Slug","Stealth","Utility"],"summary":"Remain permanently Broken, but leave no Blood, make no Injured/Dying pain sounds, recover 25% faster, and fully self-recover from the ground.","metaStatus":"Situational","skillLevel":"Very High","soloQ":1,"swf":3,"unlockPriority":"Low","glossaryKeys":["broken","dying-state","anti-slug"],"useCases":["Guarantee that slugging can never permanently keep you on the ground.","Run silent Injured-state builds with permanent Resilience access.","Use in coordinated challenge or recovery strategies that plan around permanent injury."],"counters":["The Killer knows immediately that you can only take one normal hit before going down.","Permanent Broken removes ordinary healing and most healthy-state protection.","A Killer can simply pick you up instead of slugging."],"pros":["Unlimited full self-recovery from the Dying State.","No Blood and completely silent pain sounds.","Permanent Injured state guarantees injured-only perk activation."],"cons":["Permanent Broken is one of the largest self-imposed downsides in the game.","Telegraphs the perk and recovery threat immediately.","Can make ordinary chases dramatically less forgiving."],"analysis":["No Mither contains several genuinely powerful effects and pays for them with one enormous drawback. Unlimited full ground recovery, faster recovery, no Blood, and complete pain-sound suppression would be excellent if the user were not permanently Broken.","Permanent injury means the Killer needs one normal damaging hit to down you throughout the Trial. The Killer also sees the Broken state immediately, so the anti-slug threat is never a surprise.","The perk becomes more coherent in a dedicated build. Resilience is always active, Dead Hard remains available while injured, and Tenacity or Soul Guard can strengthen the recovery plan.","Even then, No Mither is a deliberate handicap for most players. Its toolkit is real enough to avoid absolute last place, but the permanent health-state cost dominates the evaluation."],"verdict":"Several good perks wearing a permanent-Broken trench coat. No Mither has real build tech, but the price of admission is being one hit from the ground all match.","publicationStatus":"published","tags":["Challenge"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"David King"},"synergyPerkIds":["resilience","dead-hard","tenacity","soul-guard"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Resilience","Dead Hard","Tenacity","Soul Guard"],"antiSynergies":[],"name":"No Mither","alternateName":null,"source":"David King","status":"Live 10.2.0","currentEffect":"You are permanently afflicted with Broken. You leave no Pools of Blood and your Grunts of Pain are fully suppressed while Injured or in the Dying State. You can fully recover from the Dying State, recovering 15/20/25% faster according to perk tier.","activation":["The perk is equipped; its Broken effect applies from the start of the Trial.","Enter the Dying State to use the unlocked full self-recovery ability.","Ends/deactivates when: Broken and the sound/blood suppression are permanent while the perk is equipped; self-recovery is available only while in the Dying State."],"patchNote":"Latest live balance change (9.2.0): Increased Grunts of Pain volume reduction to 100% at all tiers from 25/50/75%.","plainEnglishSummary":"You remain Broken but make no blood pools or pain grunts and can fully recover from the Dying State faster.","cooldown":null,"duration":["Broken: permanent for the Trial while equipped.","Self-recovery speed bonus: while recovering from the Dying State; no separate duration."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":["Broken"],"specialInteractions":["No Mither allows a Survivor to complete self-recovery to full while in the Dying State; it does not remove the Broken status."],"sourceCharacter":"David King","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"hardened","rank":155,"tier":"C","roles":["Information","Stealth","Utility"],"summary":"After opening a chest and cleansing or blessing a Totem, all future screams are suppressed and replaced with a Killer Aura reveal for up to 5 seconds.","metaStatus":"Situational","skillLevel":"Medium","soloQ":2,"swf":3,"unlockPriority":"Low–Medium","glossaryKeys":["aura-reading","pressure"],"useCases":["Turn Killer scream-information perks into reciprocal Killer Aura reads.","Suppress scream-based tracking for the remainder of the Trial once fully activated.","Use chest and Totem interactions from an existing build to reduce the setup tax."],"counters":["Requires both a Chest unlock and a Totem cleanse or blessing before activation.","Some matches contain little or no scream-based Killer information.","Setup time can be substantial."],"pros":["Permanent once activated.","Converts an enemy information trigger into your own information.","Can hard-counter certain scream-heavy builds."],"cons":["Two separate setup tasks.","Matchup-dependent payoff.","Very weak if the Killer never makes you scream."],"analysis":["Hardened closes this band because its active effect is clever but the startup cost is enormous. You must first unlock a chest and interact with a Totem before the perk begins functioning at all.","Once active, the effect can be excellent against scream-heavy information. Every would-be scream is suppressed and converted into a Killer Aura read, simultaneously denying the Killer a cue and giving you one.","The problem is that the player pays the setup cost before knowing how often the payoff will matter. A Killer with no relevant scream effects can leave Hardened functionally blank after you already spent time opening and cleansing.","That combination of expensive activation and matchup dependency places Hardened at the bottom of B. In the right counter-build it is satisfying and strong; as a blind queue perk it is too speculative."],"verdict":"A clever hard counter buried under two setup chores. Hardened is excellent against the right scream build and difficult to justify before you know the matchup.","publicationStatus":"published","tags":["Aura Reading","Scream Suppression","Setup"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Lara Croft"},"synergyPerkIds":["detective-s-hunch","inner-strength","plunderers-instinct","residual-manifest"],"synergyOther":[],"antiSynergyPerkIds":["calm-spirit"],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Detective's Hunch","Inner Strength","Plunderer's Instinct","Residual Manifest"],"antiSynergies":["Calm Spirit"],"name":"Hardened","alternateName":null,"source":"Lara Croft","status":"Live 10.2.0","currentEffect":"After you unlock a Chest and cleanse or bless a Totem, Hardened activates for the rest of the Trial. Whenever you would scream for any reason, the scream is suppressed and the Killer's Aura is revealed to you instead for 3/4/5 seconds.","activation":["Unlock a Chest.","Cleanse or bless a Totem; both the Chest and Totem conditions must be completed.","Ends/deactivates when: The perk remains active for the rest of the Trial after both activation actions."],"patchNote":"Latest live balance change (unknown): No material live balance change could be verified from available patch history.","plainEnglishSummary":"After opening a Chest and interacting with a Totem, your screams are replaced by brief Killer Aura reveals.","cooldown":null,"duration":["Perk activation persists for the rest of the Trial.","Each Killer Aura reveal lasts 3/4/5 seconds (Tier I/II/III)."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":["Any event that would make you scream can trigger the effect; the scream is suppressed and replaced with the Killer Aura reveal."],"sourceCharacter":"Lara Croft","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"ace-in-the-hole","rank":156,"tier":"C","roles":["Item","Objective"],"summary":"Items taken from Chests gain a guaranteed Add-on, may gain a second Add-on, and keep their Add-ons if you escape.","metaStatus":"Situational","skillLevel":"Low","soloQ":2,"swf":2,"unlockPriority":"Low","glossaryKeys":[],"useCases":["Improve the expected quality of chest loot.","Pair with Plunderer’s Instinct and Appraisal to generate better-equipped Items.","Escape with valuable Add-ons instead of losing them."],"counters":["Only regular Items retrieved from Chests receive the Add-ons.","The base Item itself can still be something you do not need.","No immediate match value if you never open a Chest."],"pros":["Guaranteed Add-on on chest Items.","Tier III always rolls a second Add-on chance at 100%.","Add-ons can be retained on escape."],"cons":["Completely chest-dependent.","Random resource identity and Add-ons.","No direct chase, repair, healing, or rescue effect."],"analysis":["Ace in the Hole improves the quality of an activity that is already optional: looting Chests. The perk guarantees one Add-on and can guarantee a second at Tier III, which is meaningful when the Item itself is useful.","Its strongest role is inside a full loot economy. Plunderer’s Instinct finds and accelerates Chests, Appraisal produces more Items, and Ace in the Hole improves what those Items contain.","The weakness is that no amount of Add-on quality makes a badly timed chest detour efficient. The team still needs generators, rescues, and chase time more urgently than random loot in many matches.","That keeps Ace in the Hole low despite solid synergy. It improves chest output rather than solving the fundamental opportunity cost of opening Chests."],"verdict":"A good chest-build multiplier and a weak general perk. Better loot is nice; needing loot in the first place is the harder argument.","publicationStatus":"published","tags":["Chest","Resource"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Ace Visconti"},"synergyPerkIds":["plunderers-instinct","appraisal","pharmacy","streetwise"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Plunderer's Instinct","Appraisal","Pharmacy","Streetwise"],"antiSynergies":[],"name":"Ace in the Hole","alternateName":null,"source":"Ace Visconti","status":"Live 10.2.0","currentEffect":"Regular Items retrieved from Chests come with one guaranteed Add-on of Visceral Rarity or lower and a 50/75/100% chance of a second Add-on of Uncommon Rarity or lower. Add-ons on your held Item are retained when you escape.","activation":["Retrieve a regular Item from a Chest."],"patchNote":"Latest live balance change (8.4.0): Raised the guaranteed Add-on rarity cap to Ultra Rare and increased the tiered second-Add-on chance to 50/75/100%.","plainEnglishSummary":"Chest Items receive a guaranteed Add-on and may receive a second; their Add-ons are kept on escape.","cooldown":null,"duration":[],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":["Does not add these effects to non-Chest Items."],"sourceCharacter":"Ace Visconti","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"corrective-action","rank":157,"tier":"C","roles":["Team Support","Skill Check"],"summary":"Bank Tokens from Great Skill Checks and automatically convert a cooperating teammate’s failed Skill Check into a Good one.","metaStatus":"Situational","skillLevel":"Low","soloQ":3,"swf":2,"unlockPriority":"Low–Medium","glossaryKeys":["pressure"],"useCases":["Protect cooperative generators from a teammate miss.","Support newer players during heals or repairs without interrupting the action.","Replenish Tokens through your own Great Skill Checks."],"counters":["It only helps teammates performing a cooperative action with you.","Experienced teammates may rarely fail a Skill Check.","Tokens are wasted if the team mostly works separately."],"pros":["Starts with Tokens and can replenish them.","A prevented generator miss can save a large chunk of progress.","Passive once the co-op action is underway."],"cons":["Value depends on someone else making a mistake.","No benefit while working alone.","Much weaker in experienced teams."],"analysis":["Corrective Action is one of those perks whose value depends more on the lobby than on the Killer. In a team with inconsistent Skill Checks, one prevented failure can save a meaningful amount of generator or healing progress.","The perk starts with Tokens and earns more from the user’s Great Skill Checks, so a mechanically strong player can effectively insure a weaker teammate during cooperative actions.","In experienced groups the trigger becomes rare, and the perk cannot create extra progress when nobody makes mistakes. That makes its ceiling practical rather than competitive.","It belongs above true gimmicks because the prevention is automatic and can save real time, but its value shrinks as the team improves."],"verdict":"Excellent insurance for co-op Skill Check mistakes, increasingly unnecessary as teammates become consistent. A useful teaching/support perk rather than a meta engine.","publicationStatus":"published","tags":["Co-op","Beginner Support"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Jonah Vasquez"},"synergyPerkIds":["prove-thyself","friendly-competition","better-together","hyperfocus"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Prove Thyself","Friendly Competition","Better Together","Hyperfocus"],"antiSynergies":[],"name":"Corrective Action","alternateName":null,"source":"Jonah Vasquez","status":"Live 10.2.0","currentEffect":"Start with 1/2/3 Tokens, up to 5. Completing a Great Skill Check grants 1 Token. While cooperating with another Survivor on an action that causes Skill Checks, a Token is spent when they fail a Skill Check to turn it into a Good Skill Check; their Aura is revealed to you for 6 seconds.","activation":["Start with tier-dependent Tokens.","Great Skill Checks grant a Token.","Cooperate with another Survivor on an action that causes Skill Checks when they fail.","Ends/deactivates when: Tokens are spent when converting a failed teammate Skill Check."],"patchNote":"Latest live balance change (8.3.0): Changed starting Tokens to 1/2/3 and maximum Tokens to 5.","plainEnglishSummary":"Your tokens can convert a teammate's failed cooperative Skill Check into a Good one and reveal their Aura.","cooldown":null,"duration":["Teammate Aura reveal: 6 seconds."],"tokenOrStackBehavior":"Starts with 1/2/3 Tokens; gain 1 on Great Skill Check; maximum 5; spend 1 to convert a teammate's failed cooperative check.","oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":["Applies to another Survivor performing a Skill Check during a cooperative action with you."],"sourceCharacter":"Jonah Vasquez","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"change-of-plan","rank":158,"tier":"C","roles":["Item","Utility","Healing"],"summary":"Start with two Tokens and transform a non-event Toolbox in a Locker into a same-rarity Med-Kit with full Tier III charges and a random same-rarity Add-on.","metaStatus":"Situational","skillLevel":"Low–Medium","soloQ":2,"swf":3,"unlockPriority":"Medium","glossaryKeys":["reset"],"useCases":["Use a Toolbox for early objective pressure, then convert it into healing utility later.","Transform a depleted or less-needed Toolbox rather than carrying an irrelevant Item through the rest of the Trial.","Use a second found Toolbox for the remaining Token if the match provides one."],"counters":["Requires holding a qualifying Toolbox and entering a Locker.","The conversion destroys the Toolbox identity and its Add-ons.","The random Med-Kit Add-on may not suit the situation."],"pros":["Strong item-role flexibility.","Two Tokens allow another conversion if you acquire another Toolbox.","Same-rarity Med-Kit keeps high-quality Item value."],"cons":["Requires a Toolbox in the first place.","Locker and conversion setup costs time.","Random Add-on reduces planning precision."],"analysis":["Change of Plan ranks around the C transition because its best use is clever resource sequencing rather than raw power. A Survivor can bring a Toolbox, spend its useful generator charges early, then convert that Item slot into a Med-Kit later instead of carrying an exhausted resource.","The same-rarity conversion is important. A valuable Toolbox becomes a correspondingly valuable Med-Kit rather than a generic low-grade item, and the Tier III version supplies the new Med-Kit at full charges.","The cost is commitment. The Toolbox is gone, its original Add-ons no longer matter, and the new Add-on is random. You also need a Locker and the correct moment to perform the conversion.","In a deliberate item-economy build, Change of Plan is a neat way to extract two roles from one starting Item. In a normal build, carrying the resource you actually want from the beginning is usually simpler."],"verdict":"A flexible item-economy perk for players who want early Toolbox pressure and later healing. Clever, useful, and more complicated than simply bringing the right Item.","publicationStatus":"published","tags":["Flexibility"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Dustin Henderson"},"synergyPerkIds":["built-to-last","streetwise","pharmacy","plunderers-instinct"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Built to Last","Streetwise","Pharmacy","Plunderer's Instinct"],"antiSynergies":[],"name":"Change of Plan","alternateName":null,"source":"Dustin Henderson","status":"Live 10.2.0","currentEffect":"Start with 2 Tokens. While inside a Locker and holding a non-event Toolbox, use the Active Ability button to spend 1 Token and transform the Toolbox into a Med-Kit of the same rarity with a random Add-on of the same rarity. The new Med-Kit has 80/90/100% of its charges.","activation":["Have a Token and a non-event Toolbox.","Be in a Locker and use the Active Ability button.","Ends/deactivates when: Transformation ends after use; cannot be used without a Token or Toolbox."],"patchNote":"Latest live balance change (9.4.0): Introduced; no later material live balance change located in the official notes checked.","plainEnglishSummary":"Spend tokens in a Locker to turn a Toolbox into a same-rarity Med-Kit with a random Add-on.","cooldown":null,"duration":["Resulting Med-Kit charges: 80/90/100% by tier."],"tokenOrStackBehavior":"Starts with 2 Tokens; spend 1 per transformation.","oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":["The old Toolbox is replaced by a same-rarity Med-Kit with one random Add-on of that rarity."],"sourceCharacter":"Dustin Henderson","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"visionary","rank":159,"tier":"C","roles":["Objective","Information","Utility"],"summary":"Continuously reveal generator Auras within 32 metres, briefly switching off after any generator is completed.","metaStatus":"Situational","skillLevel":"Low","soloQ":3,"swf":1,"unlockPriority":"Low–Medium","glossaryKeys":["aura-reading","pressure"],"useCases":["Find nearby generators on unfamiliar or indoor maps.","Reduce time spent wandering between objectives as a newer player.","Use local generator Auras when map visibility is poor."],"counters":["Déjà Vu provides stronger macro information and a repair bonus.","The 32-metre range can miss generators on large maps.","The perk deactivates briefly after generator completions."],"pros":["Extremely easy to understand.","Always-on local objective guidance outside the short deactivation.","Helpful for new players."],"cons":["Outclassed by stronger generator-information perks.","No repair-speed bonus.","Map knowledge replaces much of the value."],"analysis":["Visionary ranks this position because finding generators is genuinely useful for newer players, especially on indoor maps where line of sight is poor. A permanent local Aura removes some of the navigation friction that can make early Survivor play frustrating.","The problem is comparison. Déjà Vu shows the strategically important clustered generators and gives a repair-speed bonus on them, while Visionary merely identifies nearby objectives. That makes the latter much harder to justify once both are available.","Experienced players also internalize common generator spawn logic, gradually replacing the perk with game knowledge. The brief deactivation after a generator completes adds another small inconvenience.","Visionary is therefore respectable beginner utility but poor long-term slot efficiency. It does its job clearly; other perks simply do more."],"verdict":"A fine training-wheel generator finder that gets outgrown quickly. Visionary helps navigation, but Déjà Vu makes a stronger argument for the same slot.","publicationStatus":"published","tags":["Beginner"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Felix Richter"},"synergyPerkIds":["deja-vu","open-handed","poised","detective-s-hunch"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:audit-partial-plus-normalized"],"synergies":["Déjà Vu","Open-Handed","Poised","Detective's Hunch"],"antiSynergies":[],"name":"Visionary","alternateName":null,"source":"Felix Richter","status":"Live 10.2.0","currentEffect":"Permanently reveals Generator Auras within 32 m. Whenever a Generator is completed, Visionary is temporarily deactivated for 20/18/16 seconds.","activation":["Remain within 32 m of a Generator to see its Aura.","Ends/deactivates when: The perk deactivates for 20/18/16 seconds after a Generator is completed."],"patchNote":"Latest live balance change (unknown): No material live balance change could be verified from available patch history.","plainEnglishSummary":"Shows nearby Generator Auras, briefly switching off each time a Generator is completed.","cooldown":"20/18/16 seconds after a Generator completion","duration":["Aura reading resumes after the 20/18/16-second deactivation."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":["The deactivation is triggered whenever any Generator is completed."],"sourceCharacter":"Felix Richter","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"rapid-response","rank":160,"tier":"C","roles":["Information","Exhaustion"],"summary":"Whenever you become Exhausted, briefly reveal the Killer's Aura; fast-exiting a Locker can voluntarily apply a short Exhausted timer.","metaStatus":"Situational","skillLevel":"Medium","soloQ":3,"swf":2,"unlockPriority":"Medium","glossaryKeys":["exhausted","aura-reading"],"useCases":["Add a short Killer Aura read to Sprint Burst, Lithe, Dramaturgy, or other Exhaustion activations.","Use a fast Locker exit to trigger the information deliberately when you are not already Exhausted.","Pair with Vigil to shorten the voluntary Exhaustion tax."],"counters":["The Aura read lasts only two seconds.","Voluntarily becoming Exhausted can disable stronger chase perks when mistimed.","Fast Locker exits are noisy and require a Locker."],"pros":["Naturally piggybacks on popular Exhaustion perks.","Player can force a trigger through a Locker.","Vigil makes the short voluntary Exhaustion easier to manage."],"cons":["Very short information duration.","Can sabotage your own Exhaustion perk.","Low standalone impact."],"analysis":["Rapid Response ranks this position because it can attach useful information to an event strong Survivor builds already create: becoming Exhausted. Sprint Burst, Dramaturgy, Lithe, and similar perks all become two-second Killer Aura triggers for free.","Two seconds is short but not meaningless. It can tell you which side of a structure the Killer chose after your burst or whether they abandoned chase entirely. Eyes of Belmont can extend that small window.","The Locker activation exists as a manual information button, but voluntarily inflicting Exhausted can be actively harmful when your real chase perk is ready. The user must understand which resource they are spending.","Rapid Response remains C because the information is brief and the manual trigger is awkward. It is best as garnish on an Exhaustion build rather than the reason the build exists."],"verdict":"A neat Exhaustion-information rider, not a core perk. Rapid Response adds two seconds of Killer vision to strong chase tools, but careless manual use can shut those tools off.","publicationStatus":"published","tags":["Aura Reading"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Orela Rose"},"synergyPerkIds":["vigil","sprint-burst","dramaturgy","eyes-of-belmont"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Vigil","Sprint Burst","Dramaturgy","Eyes of Belmont"],"antiSynergies":[],"name":"Rapid Response","alternateName":null,"source":"Orela Rose","status":"Live 10.2.0","currentEffect":"Whenever you become afflicted by Exhausted, Rapid Response reveals the Killer's Aura to you for 2 seconds. You can voluntarily trigger Exhausted by Fast Exiting a Locker; this applies Exhausted for 30/25/20 seconds by tier. Rapid Response cannot override an Exhausted effect that is already active.","activation":["Become afflicted by Exhausted to reveal the Killer's Aura.","To voluntarily trigger the perk, Fast Exit a Locker while not already Exhausted.","Ends/deactivates when: Killer Aura reveal ends after 2 seconds.","Ends/deactivates when: The voluntary Exhausted effect lasts 30/25/20 seconds by tier; the perk cannot override an existing Exhausted effect."],"patchNote":"Latest live balance change (8.7.0): Introduced; no later material live balance change located in the official notes checked.","plainEnglishSummary":"Gaining Exhausted reveals the Killer's Aura to you briefly, and a Fast Locker Exit can trigger tier-scaled Exhaustion voluntarily.","cooldown":null,"duration":["Killer Aura reveal: 2 seconds.","Exhausted from Fast Exiting a Locker: 30/25/20 seconds by tier."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":["Exhausted"],"specialInteractions":["The aura reveal also triggers when Exhausted is applied by another source; the perk cannot override an already active Exhausted status."],"sourceCharacter":"Orela Rose","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"slippery-meat","rank":161,"tier":"D","roles":["Rescue","Anti-Tunnel","Mobility"],"summary":"Teammates unhook you up to 100% faster, and every unhook gives you 5% additional Haste; it no longer improves self-unhook attempts.","metaStatus":"Weak","skillLevel":"Low","soloQ":2,"swf":2,"unlockPriority":"Low","glossaryKeys":["hook-state","swf"],"useCases":["Reduce the rescue interaction window when teammates unhook you, especially under hook pressure.","Use the extra post-unhook Haste to create separation immediately after the rescue.","Explore coordinated endgame rescue packages with No One Left Behind and other post-unhook movement support."],"counters":["It only helps while you are the hooked Survivor, so many matches provide little or no value.","Unhooking is already a short interaction, which limits the raw time saved by the speed bonus.","Hex: Under Your Thumb can cap running Haste while it remains lit."],"pros":["No setup is required before you are hooked.","Faster rescues can matter in tight camping or endgame windows.","The additional Haste stacks conceptually with a broader rescue package, though exact stacking should not be assumed without testing."],"cons":["Very narrow global use case.","Most of the high-end value depends on coordinated rescue situations.","Later live gameplay raised its package ceiling, but did not establish a global-rank promotion."],"analysis":["Slippery Meat has a completely different identity in live 10.2: its former Luck-based self-rescue identity is gone. The perk now makes other Survivors unhook you faster and gives you additional Haste after the rescue.","Its generic value is still narrow because the perk only contributes while you are the hooked player, and the unhook interaction itself is short. That supports keeping its global rank low for now.","Later live gameplay evidence does reopen one question the earlier ranking defense treated as settled: coordinated endgame rescue packages can exploit the faster unhook plus post-rescue movement in ways that are more valuable than the generic ranking suggests.","For v15, global rank and specialized package value therefore stay separate. The global rank remains provisional while the endgame/SWF ceiling is explicitly marked for further review."],"verdict":"Low generic value, but no longer safe to dismiss as simple bottom-tier filler. Its coordinated endgame-rescue ceiling is reopened for review.","publicationStatus":"published","reviewFlags":["10.2-live-change","v15-schema-migrated","rank-review-applied","queue-rating:audit-explicit"],"tags":["Haste"],"queueRatingStatus":"reviewed","rankRange":[155,168],"rankConfidence":"Low","rankStatus":"reopened","evidenceStatus":"reopened-live-evidence","acquisition":{"type":"general","sourceCharacter":"General"},"synergyPerkIds":["no-one-left-behind","babysitter","borrowed-time","overcome","resurgence"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[{"archetype":"Coordinated endgame rescue package","grade":null,"requiresPerkIds":["no-one-left-behind"],"status":"needs-review","note":"Later live gameplay supports a materially higher package ceiling than the global rank, but did not establish a new global placement."},{"archetype":"Coordinated endgame rescue","grade":"B (provisional)","requires":["no-one-left-behind"],"note":"Later live gameplay materially raised the package ceiling, especially when faster unhooks and post-rescue movement are stacked. Global rank remains low pending broader evidence.","confidence":"Low"}],"synergies":["No One Left Behind","Babysitter","Borrowed Time","Overcome","Resurgence"],"antiSynergies":[],"name":"Slippery Meat","alternateName":null,"source":"General perk","status":"Live 10.2.0","currentEffect":"Other Survivors unhook you 90/95/100% faster. Whenever you are unhooked, you gain 5% more Haste.","activation":["Another Survivor unhooks you for the unhook-speed effect.","Be unhooked to receive 5% more Haste.","Ends/deactivates when: The unhook-speed modifier applies only while another Survivor is unhooking you.","Ends/deactivates when: The additional Haste follows the post-unhook Haste effect's duration."],"patchNote":"Latest live balance change (10.2.0): Complete rework: removed self-unhook attempt/chance bonuses; other Survivors now unhook you 90/95/100% faster and you gain 5% more Haste when unhooked.","plainEnglishSummary":"Teammates unhook you much faster, and being unhooked increases your post-unhook Haste.","cooldown":null,"duration":["The 5% additional Haste follows the duration of the post-unhook Haste effect."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":["Haste"],"specialInteractions":["The unhook-speed bonus applies when another Survivor unhooks you; the 5% Haste increase applies when you are unhooked."],"sourceCharacter":"General","isGeneralPerk":true,"currentLivePatchVerified":"10.2.0"},{"id":"teamwork-toughen-up","rank":162,"tier":"D","roles":["Stealth","Team Support","Chase"],"summary":"While injured, a nearby teammate blinding or pallet-stunning the Killer suppresses your pain sounds, Blood, and Scratch Marks for up to 30 seconds.","metaStatus":"Weak","skillLevel":"Medium–High","soloQ":1,"swf":2,"unlockPriority":"Medium","glossaryKeys":["looping","swf"],"useCases":["Use a teammate's stun or blind to disappear during a group chase or rescue.","Break line of sight during the thirty-second suppression window and change routes completely.","Pair with coordinated save builds where nearby teammate stuns are planned rather than accidental."],"counters":["You must be injured and within 24 metres of the teammate's blind or pallet stun.","The perk relies on someone else successfully performing the interaction.","Direct sight and Aura reading can still reveal you."],"pros":["Thirty seconds is a long tracking-denial window.","Suppresses three major chase cues.","Excellent coordinated rescue synergy."],"cons":["Zero solo activation control.","Highly event-dependent.","Requires the team to cluster around Killer interactions."],"analysis":["Teamwork: Toughen Up follows Throw Down because thirty seconds without pain sounds, Blood, or Scratch Marks is a substantial escape window. The difference is that another Survivor must create the blind or pallet stun while you are injured nearby.","That can be devastating in a planned rescue. A teammate stuns the Killer, the perk activates, and the injured Survivor suddenly loses most conventional tracking cues while everyone scatters.","Normal matchmaking is much less cooperative. Teammates may never land the relevant interaction within twenty-four metres, and the user has no button that can force the perk to happen.","The effect is strong enough to respect but too externally controlled for a higher slot. Toughen Up belongs to the family of SWF perks that can look absurd in a montage and invisible in ordinary queues."],"verdict":"Thirty seconds of near-total trail suppression is excellent, but somebody else has to win the interaction for you. Toughen Up is coordinated-stealth tech, not general reliability.","publicationStatus":"published","tags":["Team","Chase Escape"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Rick Grimes"},"synergyPerkIds":["teamwork-throw-down","background-player","flashbang","lucky-break"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Teamwork: Throw Down","Background Player","Flashbang","Lucky Break"],"antiSynergies":[],"name":"Teamwork: Toughen Up","alternateName":null,"source":"Rick Grimes","status":"Live 10.2.0","currentEffect":"While injured, whenever another Survivor within 24 m blinds the Killer by any means or stuns them using a Pallet, suppresses your Grunts of Pain, Pools of Blood, and Scratch Marks for 20/25/30 seconds.","activation":["You must be injured.","Another Survivor within 24 m must blind or Pallet-stun the Killer.","Ends/deactivates when: Suppression ends after 20/25/30 seconds."],"patchNote":"Latest live balance change (9.1.0): Introduced; no later material live balance change located in the official notes checked.","plainEnglishSummary":"When a nearby teammate blinds or Pallet-stuns the Killer, your tracking traces are suppressed for a short time while injured.","cooldown":null,"duration":["Grunts of Pain, Pools of Blood, and Scratch Marks are suppressed for 20/25/30 seconds."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":["The perk suppresses Grunts of Pain, Pools of Blood, and Scratch Marks; it does not name an Elusive status effect."],"sourceCharacter":"Rick Grimes","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"low-profile","rank":163,"tier":"D","roles":["Stealth","Utility"],"summary":"When you are the only active Survivor not downed, carried, or hooked, suppress your pain sounds, Blood, and Scratch Marks for up to 90 seconds.","metaStatus":"Weak","skillLevel":"Low–Medium","soloQ":2,"swf":1,"unlockPriority":"Medium","glossaryKeys":["dying-state","hook-state","looping"],"useCases":["Disappear while the rest of the team is simultaneously incapacitated.","Use the long stealth window to attempt pickups, rescues, or a reset without leaving normal tracking cues.","Benefit again if the condition later becomes true another time."],"counters":["The team must already be in an extremely bad state.","The perk does nothing during normal four-player pressure.","Direct sight, Aura reading, and Killer-specific tracking can still find you."],"pros":["Ninety seconds is an enormous suppression window.","Can activate multiple times.","Suppresses three important tracking channels."],"cons":["Pure comeback condition.","Often activates when the match is already close to lost.","No speed, health-state, or rescue bonus."],"analysis":["Low Profile ranks this position because its active effect is genuinely strong and its trigger is genuinely awful. Ninety seconds without Scratch Marks, Blood, or Grunts can make one remaining active Survivor remarkably hard to track while everyone else is incapacitated.","That creates real comeback opportunities. The user may be able to reach a slugged teammate, approach a hook, or force the Killer to search instead of immediately completing a snowball.","The problem is that the perk asks the team to be collapsing before it turns on. A slot that contributes nothing to preventing the snowball cannot be ranked as though the ninety-second stealth were available in normal game states.","Low Profile is therefore a respectable emergency perk and poor general prevention. It helps when the fire is already roaring rather than stopping anyone from dropping the matchbox."],"verdict":"A massive stealth window triggered by a terrible situation. Low Profile can help salvage a snowball, but it spends most healthy matches waiting for disaster.","publicationStatus":"published","tags":["Comeback","Tracking Denial"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Ada Wong"},"synergyPerkIds":["self-preservation","lucky-break","iron-will","unbreakable"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Self-Preservation","Lucky Break","Iron Will","Unbreakable"],"antiSynergies":[],"name":"Low Profile","alternateName":null,"source":"Ada Wong","status":"Live 10.2.0","currentEffect":"Whenever you are the only Survivor in the Trial not currently incapacitated by being downed, carried, or hooked, Low Profile activates. For 70/80/90 seconds it suppresses your Grunts of Pain and the creation of Pools of Blood and Scratch Marks. It deactivates after use, counts only Survivors still participating in the Trial, and can activate multiple times if its condition is met again.","activation":["Be the only Survivor still participating in the Trial who is not downed, carried, or hooked.","Ends/deactivates when: The activation ends after 70/80/90 seconds; the perk may activate again if its condition is met later in the Trial."],"patchNote":"Latest live balance change (6.2.0): The live activation condition was broadened from last Survivor standing to being the only Survivor not incapacitated, enabling multiple activations in a Trial.","plainEnglishSummary":"When you are the only active Survivor still in the Trial, it hides your pain sounds and tracking traces for a tier-based duration.","cooldown":null,"duration":["Suppression effect: 70/80/90 seconds by tier."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":"Not limited to one use per Trial; it can activate more than once when the condition is met again.","statusEffectsInvolved":[],"specialInteractions":["Survivors who have left the Trial are not counted toward its activation condition."],"sourceCharacter":"Ada Wong","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"teamwork-collective-stealth","rank":164,"tier":"D","roles":["Stealth","Team Support","Healing"],"summary":"After another Survivor finishes healing you, both of you suppress Scratch Marks while you remain within up to 16 metres of each other.","metaStatus":"Weak","skillLevel":"Low–Medium","soloQ":1,"swf":2,"unlockPriority":"Medium","glossaryKeys":["swf","reset"],"useCases":["Leave a healing area together without advertising either Survivor's sprint trail.","Use the linger to split briefly before deciding whether to re-enter the tether.","Pair with Blood Pact or other two-person movement builds."],"counters":["Requires another Survivor to heal you fully.","The effect demands close proximity after the heal.","Grouping two Survivors can reduce generator spread and invite multi-target pressure."],"pros":["Applies to both players.","No fixed duration while the tether remains active.","Useful immediately after a vulnerable healing interaction."],"cons":["Tether is strategically awkward.","Scratch Marks are only one tracking channel.","Solo Q teammates rarely cooperate with the proximity requirement."],"analysis":["Teamwork: Collective Stealth ranks this position because suppressing two Survivors' Scratch Marks can create a clean rotation after a heal, but the perk asks them to remain close enough that the Killer may pressure both at once.","The no-duration design is interesting. As long as the pair respects the range, the stealth continues, and the brief linger allows momentary separation. A coordinated duo can deliberately move through indoor structures without leaving the normal trail.","Macro pressure is the problem. Survivors usually want to heal and then split toward different objectives. Collective Stealth rewards the opposite behavior, making its strongest state inherently expensive.","This is another Teamwork perk whose ceiling belongs to premades. In Solo Q, the other player usually runs away with their own plan before you have a chance to exploit the effect."],"verdict":"A functional two-person stealth tether with an awkward macro cost. Collective Stealth works when staying together is already the plan, and fights the game when it is not.","publicationStatus":"published","tags":["Team"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Renato Lyra"},"synergyPerkIds":["blood-pact","teamwork-power-of-two","boon-shadow-step","empathic-connection"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Blood Pact","Teamwork: Power of Two","Boon: Shadow Step","Empathic Connection"],"antiSynergies":[],"name":"Teamwork: Collective Stealth","alternateName":null,"source":"Renato Lyra","status":"Live 10.2.0","currentEffect":"Whenever another Survivor finishes healing you, both you and that Survivor who healed you suppress Scratch Marks while within 8/12/16 m of one another. The effect lingers for 4 seconds after leaving range and resumes if you re-enter range before the linger ends. Survivors can only be affected by one instance of Teamwork: Collective Stealth at a time.","activation":["Another Survivor must finish healing you.","Both Survivors must remain within 8/12/16 m to keep the shared effect active.","Ends/deactivates when: The effect ends 4 seconds after leaving range unless you re-enter before the timer ends."],"patchNote":"Latest live balance change (unknown): No material live balance change could be verified from available patch history.","plainEnglishSummary":"After another Survivor heals you, both of you hide Scratch Marks while staying close together.","cooldown":null,"duration":["Continues while within range; lingers for 4 seconds after leaving range."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":"A Survivor can be affected by only one instance of this perk at a time.","statusEffectsInvolved":[],"specialInteractions":["The effect applies to both the healed Survivor and the Survivor who healed them."],"sourceCharacter":"Renato Lyra","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"teamwork-soft-spoken","rank":165,"tier":"D","roles":["Objective","Team Support","Stealth"],"summary":"While repairing with at least one teammate, repair 5% faster; each other Survivor also reduces the distance at which the generator's repair noise can be heard.","metaStatus":"Weak","skillLevel":"Low","soloQ":1,"swf":2,"unlockPriority":"Medium","glossaryKeys":["pressure","swf"],"useCases":["Add a modest repair bonus when the team deliberately stacks a generator.","Make cooperative generator work quieter on indoor or low-visibility maps.","Combine with other co-op perks during a planned burst repair."],"counters":["Provides nothing while repairing alone.","Five percent does not make inefficient generator stacking automatically good.","Quiet generator audio matters less when the Killer already knows the objective location."],"pros":["Simple always-on co-op bonus.","Combines speed and stealth.","No cooldown or token economy."],"cons":["Zero solo value.","Lower ceiling than Prove Thyself or Friendly Competition.","Requires grouping Survivors on one objective."],"analysis":["Teamwork: Soft-Spoken lands at this position because five percent faster cooperative repair is useful, but Survivors do not need another excuse to over-stack generators. The bonus is best when two players already have a strategic reason to finish one objective immediately.","The quieter repair noise can help on indoor maps, especially when walls prevent the Killer from visually confirming the generator. With multiple teammates, the audible-distance reduction stacks through each additional Survivor.","The perk is easy to use and equally easy to overvalue. A five-percent modifier cannot repay every second lost by putting multiple Survivors on one generator instead of spreading map pressure.","That leaves Soft-Spoken as a modest co-op specialist. It has a clean floor when the trigger exists and no value at all when you are repairing alone."],"verdict":"A small co-op repair and stealth bonus that should follow good macro, not dictate it. Soft-Spoken is fine when stacking is already correct.","publicationStatus":"published","tags":["Co-op"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Eleven"},"synergyPerkIds":["prove-thyself","friendly-competition","teamwork-full-circuit","better-together"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Prove Thyself","Friendly Competition","Teamwork: Full Circuit","Better Together"],"antiSynergies":[],"name":"Teamwork: Soft-Spoken","alternateName":null,"source":"Eleven","status":"Live 10.2.0","currentEffect":"For each other Survivor repairing a Generator with you, reduces the range at which its repair noises are heard by 15/20/25%. While repairing with at least one other Survivor, you repair 5% faster.","activation":["Repair a Generator with at least one other Survivor for the 5% repair-speed bonus.","Each other Survivor repairing with you increases the noise-range reduction.","Ends/deactivates when: Bonuses end when you stop repairing with the other Survivor or Survivors."],"patchNote":"Latest live balance change (9.4.0): Introduced; no later material live balance change located in the official notes checked.","plainEnglishSummary":"Cooperative repairs are faster and quieter for each teammate working on the Generator with you.","cooldown":null,"duration":[],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":["The noise-range reduction scales for each other Survivor on the same Generator."],"sourceCharacter":"Eleven","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"up-the-ante","rank":166,"tier":"D","roles":["Utility","Rescue","Team Support"],"summary":"Grant teamwide Luck based on how many other Survivors remain alive, primarily affecting self-unhook chance; its old Slippery Meat combo no longer exists.","metaStatus":"Weak","skillLevel":"Low–Medium","soloQ":1,"swf":2,"unlockPriority":"Low","glossaryKeys":["hook-state","swf"],"useCases":["Give every Survivor access to first-stage self-unhook attempts without needing Deliverance.","Use in a coordinated team that wants to split pressure and reduce rescue obligations."],"counters":["Luck has almost no meaningful purpose outside self-unhook chance.","One copy alone still leaves self-unhooks unreliable compared with deterministic rescue perks.","The perk loses Luck as Survivors die, exactly when the team is already under pressure."],"pros":["Teamwide effect from one perk slot.","Unlocks a mechanic Survivors normally cannot rely on.","Scales brutally when multiple copies and Luck offerings are coordinated."],"cons":["Weak as a casual standalone perk.","RNG can fail at the worst moment.","Full ceiling demands heavy SWF coordination and multiple loadout commitments."],"analysis":["Up the Ante itself did not receive a 10.2 rework, but its practical ranking changed because Slippery Meat did. The old six-attempt Luck package that made coordinated self-unhook teams notorious is gone.","Teamwide Luck can still improve self-unhook odds and can still stack across a coordinated team, but it now has far less leverage without Slippery Meat multiplying the number of attempts.","That leaves an unusually narrow perk whose main outcome is still random. A safe normal rescue remains preferable whenever one is available.","The previous upper-B placement was built on an interaction that no longer exists and should be treated as invalid. Up the Ante now belongs in the independent reviewer’s lower-tier audit."],"verdict":"Collateral damage from the Slippery Meat rework. Up the Ante still boosts team Luck, but the coordinated self-unhook package lost the perk that made the odds explode.","publicationStatus":"published","reviewFlags":["indirect-10.2-impact","v15-schema-migrated","rank-review-applied","queue-rating:audit-explicit"],"tags":["Luck","Self-Unhook","Team"],"queueRatingStatus":"reviewed","rankRange":[160,172],"rankConfidence":"High","rankStatus":"stable","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Ace Visconti"},"synergyPerkIds":["resurgence","will-to-live"],"synergyOther":["Luck Offerings"],"antiSynergyPerkIds":[],"archetypeRatings":[{"archetype":"Coordinated Luck stack","grade":"C+/B-","requires":[],"note":"Multiple copies plus Luck offerings can raise self-unhook odds, but the old Slippery Meat attempt-multiplication package is gone.","confidence":"Low"}],"synergies":["Resurgence","Will to Live","Luck Offerings"],"antiSynergies":[],"name":"Up the Ante","alternateName":null,"source":"Ace Visconti","status":"Live 10.2.0","currentEffect":"Unlocks Self-Unhook attempts during the first Hook Stage for all Survivors. For every Survivor still in the Trial, gain 1 Token; each Token increases all Survivors' chance of succeeding at a Self-Unhook attempt by 1/2/3%, up to 3/6/9%.","activation":["Survivors must attempt a Self-Unhook during the first Hook Stage to use the added Luck.","Ends/deactivates when: The token count and Luck bonus fall as Survivors leave the Trial."],"patchNote":"Latest live balance change (unknown): No material live balance change could be verified from available patch history.","plainEnglishSummary":"Lets everyone attempt a first-stage self-unhook and improves the whole team's success chance while more Survivors remain.","cooldown":null,"duration":[],"tokenOrStackBehavior":"Gain 1 token for each Survivor still in the Trial, up to the perk's maximum 3 tokens. Each token gives all Survivors 1/2/3% more Self-Unhook success chance, for a maximum 3/6/9%.","oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":["The Luck bonus applies to every Survivor, not only the perk user."],"sourceCharacter":"Ace Visconti","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"come-and-get-me","rank":167,"tier":"D","roles":["Rescue","Stealth","Team Support"],"summary":"After unhooking, you can hide nearby injured or downed teammates' pain sounds, Blood, and Scratch Marks for up to 15 seconds, but you scream and reveal your own Aura for 5 seconds.","metaStatus":"Weak","skillLevel":"High","soloQ":1,"swf":2,"unlockPriority":"Low–Medium","glossaryKeys":["hook-state","aura-reading","swf"],"useCases":["Protect the unhooked Survivor's escape trail after a dangerous rescue.","Hide nearby slugged or injured teammates while deliberately drawing Killer attention to yourself.","Use in SWF when the team wants one Survivor to become the obvious decoy."],"counters":["You reveal yourself to the Killer.","Requires crouching and standing still to activate after an unhook.","Only helps injured or downed teammates within 24 metres."],"pros":["Can hide several teammates simultaneously.","Suppresses multiple tracking cues.","Creates a deliberate decoy role for the perk owner."],"cons":["High personal risk.","Activation is awkward after a rescue.","Requires nearby teammates to be in exactly the right states."],"analysis":["Come and Get Me! ranks this position because the effect is powerful but almost aggressively altruistic. After an unhook, the user can erase major tracking cues for nearby injured and downed teammates while explicitly screaming and showing their own Aura to the Killer.","In a coordinated team that can be a real strategy. The rescuer becomes the decoy while the unhooked Survivor and nearby injured teammates disappear from normal tracking, potentially redirecting the Killer away from a vulnerable target.","The same design is dangerous in Solo Q. Revealing yourself without knowing what teammates will do can simply hand the Killer a fresh chase. The crouched, motionless activation also asks for a tiny setup window during an already hectic rescue.","The perk has enough teamplay potential for C, but its risk is not theoretical. You are buying stealth for others with your own visibility."],"verdict":"A deliberate decoy perk for coordinated altruism. Come and Get Me! can hide the team beautifully, provided you are happy to paint a target on yourself.","publicationStatus":"published","tags":["Tracking Denial","Team"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Rick Grimes"},"synergyPerkIds":["babysitter","off-the-record","teamwork-toughen-up","diversion"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Babysitter","Off the Record","Teamwork: Toughen Up","Diversion"],"antiSynergies":[],"name":"Come and Get Me!","alternateName":null,"source":"Rick Grimes","status":"Live 10.2.0","currentEffect":"After unhooking a Survivor, while crouched and motionless press the Active Ability button. Injured or Dying Survivors within 24 metres suppress their Grunts of Pain, Pools of Blood and Scratch Marks for 10/12.5/15 seconds. You scream and your Aura is revealed to the Killer for 5 seconds.","activation":["Unhook a Survivor.","Crouch and remain motionless, then use Active Ability.","Ends/deactivates when: Suppression ends after 10/12.5/15 seconds; your Aura reveal ends after 5 seconds."],"patchNote":"Latest live balance change (9.1.0): Added suppression of Grunts of Pain to the effects on nearby injured or Dying Survivors.","plainEnglishSummary":"After an unhook, you can briefly hide nearby injured or downed teammates' trails, at the cost of revealing yourself.","cooldown":null,"duration":["Teammate suppression: 10/12.5/15 seconds.","Your Aura revealed to Killer: 5 seconds."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":["Affects injured or Dying Survivors within 24 metres; you scream and reveal your Aura to the Killer."],"sourceCharacter":"Rick Grimes","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"apocalyptic-ingenuity","rank":168,"tier":"D","roles":["Pallet","Objective","Item"],"summary":"After interacting with a chest, rebuild one broken pallet as a Fragile Pallet; the reconstructed pallet breaks immediately when dropped.","metaStatus":"Weak","skillLevel":"Medium","soloQ":1,"swf":2,"unlockPriority":"Low–Medium","glossaryKeys":["looping"],"useCases":["Restore a pallet body at a previously exhausted tile.","Use broken-pallet Aura information to identify possible rebuild locations.","Create a temporary resource the Killer must still account for during pathing."],"counters":["Requires a chest unlock or rummage first.","The Fragile Pallet breaks immediately when dropped.","Only one rebuilt pallet can be created from the perk's setup."],"pros":["Can restore interaction geometry to an exhausted tile.","Shows nearby broken pallet Auras.","Unique resource-rebuilding effect."],"cons":["Chest setup tax.","Rebuilt pallet is deliberately weak.","Often inferior to rotating to an untouched tile."],"analysis":["Apocalyptic Ingenuity ranks this position because rebuilding a pallet sounds stronger than the actual Fragile Pallet mechanic. The reconstructed resource breaks immediately when dropped, so the Survivor is not recreating a full normal pallet loop.","The effect can still matter. Restoring the pallet body changes pathing, creates a possible stun interaction, and may force the Killer to respect a resource at a tile they thought was completely exhausted.","The chest setup is the bigger issue. A Survivor must spend time unlocking or rummaging before the rebuild is available, adding a side objective before a situational chase payoff.","That keeps the perk near the bottom of the global list. It is mechanically unique and occasionally clever, but normal rotation to an existing tile is usually cheaper than manufacturing a fragile one."],"verdict":"A creative way to resurrect a dead tile, with emphasis on 'fragile.' Apocalyptic Ingenuity creates options, not a full pallet refund.","publicationStatus":"published","tags":["Resource","Chest"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Rick Grimes"},"synergyPerkIds":["appraisal","plunderers-instinct","any-means-necessary"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Appraisal","Plunderer's Instinct","Any Means Necessary"],"antiSynergies":[],"name":"Apocalyptic Ingenuity","alternateName":null,"source":"Rick Grimes","status":"Live 10.2.0","currentEffect":"You see the Auras of broken Pallets within 24/28/32 metres. After rummaging through or unlocking a Chest, hold the Active Ability button beside a broken Pallet for 3 seconds to rebuild it as a Fragile Pallet, which breaks immediately when dropped.","activation":["Rummage through or unlock a Chest.","Stand beside a broken Pallet and hold the Active Ability button for 3 seconds.","Ends/deactivates when: Fragile Pallet breaks immediately when dropped.","Ends/deactivates when: Rebuild interaction ends if interrupted."],"patchNote":"Latest live balance change (10.1.0): Changed the prerequisite to one Chest interaction and reduced rebuild interaction to 3 seconds.","plainEnglishSummary":"After a Chest interaction, you can rebuild one broken Pallet as a Fragile Pallet.","cooldown":null,"duration":["Pallet rebuild interaction: 3 seconds."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":"One Chest interaction enables one rebuild; another qualifying interaction is needed for another rebuild.","statusEffectsInvolved":[],"specialInteractions":["The rebuilt Fragile Pallet breaks immediately when dropped."],"sourceCharacter":"Rick Grimes","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"diversion","rank":169,"tier":"D","roles":["Stealth","Utility"],"summary":"Charge near the Killer outside chase, then throw a pebble that creates a fake Loud Noise notification and Scratch Marks 20 metres away.","metaStatus":"Weak","skillLevel":"Medium–High","soloQ":1,"swf":1,"unlockPriority":"Low","glossaryKeys":["terror-radius"],"useCases":["Send the Killer toward a plausible false location after a hook or patrol event.","Create fake Scratch Marks at the decoy point.","Use coordinated timing to pull a mobile Killer away from a real objective."],"counters":["The Killer can recognize implausible notifications or simply ignore them.","Stealth Killers make charging harder because Terror Radius uptime is lower.","A bad throw can point the Killer toward real teammates instead."],"pros":["Player-controlled decoy.","Can create both noise and fake trail information.","Shorter modern charge time than historical versions."],"cons":["No guaranteed Killer reaction.","Requires Terror Radius charging outside chase.","Easy to use in a way that accomplishes nothing."],"analysis":["Diversion is one of the game’s better comedy perks because the effect can also be strategically real. A well-timed fake notification can pull a Killer toward a location they believe contains a Survivor or objective mistake.","The fake Scratch Marks help sell the story if the Killer reaches the landing point, but the perk never controls whether the Killer takes the bait in the first place.","Charging requires time in the Terror Radius without being chased, which is easier against territorial standard Killers than stealth or highly mobile ones.","Diversion belongs low because misdirection is probabilistic value. Creative players can manufacture strong moments, but a perk that needs the opponent to believe the lie cannot be consistent."],"verdict":"A pebble with a résumé. Diversion can genuinely redirect a Killer, but its power begins and ends with whether the Killer believes you.","publicationStatus":"published","tags":["Misdirection"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Adam Francis"},"synergyPerkIds":["red-herring","deception","lucky-star"],"synergyOther":["Stealth builds"],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Red Herring","Deception","Lucky Star","Stealth builds"],"antiSynergies":[],"name":"Diversion","alternateName":null,"source":"Adam Francis","status":"Live 10.2.0","currentEffect":"After spending 30/25/20 seconds in the Killer's Terror Radius while not in chase, Diversion activates. While crouched and motionless, use the Active Ability button to throw a pebble up to 20 metres, creating a Loud Noise notification and fake Scratch Marks at the landing point. It deactivates after use.","activation":["Spend tier time in the Terror Radius while not in chase.","Crouch, remain motionless and use Active Ability.","Ends/deactivates when: Deactivates after the pebble is thrown."],"patchNote":"Latest live balance change (8.2.0): Reduced the Terror Radius charge time to 30/25/20 seconds.","plainEnglishSummary":"Staying near the Killer without being chased charges a pebble that creates a decoy noise and trail.","cooldown":null,"duration":[],"tokenOrStackBehavior":"Charges one use after 30/25/20 seconds in Terror Radius outside chase; one pebble per activation.","oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":["Creates a Loud Noise notification and fake Scratch Marks at the pebble landing point."],"sourceCharacter":"Adam Francis","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"rookie-spirit","rank":170,"tier":"D","roles":["Objective","Information"],"summary":"After landing three basic generator Skill Checks at Tier III, permanently reveal every generator that is currently regressing.","metaStatus":"Weak","skillLevel":"Low","soloQ":2,"swf":1,"unlockPriority":"Low–Medium","glossaryKeys":["aura-reading","pressure"],"useCases":["Identify which generators the Killer has recently kicked or otherwise forced into regression.","Return to a threatened generator before too much progress is lost.","Use regression Auras as indirect information about where the Killer has been applying pressure."],"counters":["Requires three generator Skill Checks before activation.","Does not show the Killer or tell you how much progress the generator has.","Some regression sources or game states may create information that is obvious anyway."],"pros":["Permanent activation after the initial setup.","Can protect team generator progress indirectly.","Very easy to read once active."],"cons":["Setup timing depends on Skill Check RNG.","Pure information.","Outclassed by stronger objective-information perks."],"analysis":["Rookie Spirit takes this position because seeing regressing generators can help the team identify objectives that are quietly losing progress, especially in Solo Q where nobody may call out the kick.","Once activated, the perk stays active for the rest of the Trial. The problem is getting the three repair Skill Checks early enough for the information to matter. A generator can sometimes be nearly finished before the perk has even armed.","The Auras provide indirect Killer information as well. A newly regressing generator often tells you where the Killer just spent time, though the perk does not show their current direction.","Rookie Spirit remains low C because Déjà Vu, Alert, Poised, and other objective tools provide more actionable information with fewer setup quirks."],"verdict":"A reasonable regression monitor that arrives after three Skill Checks. Rookie Spirit can save unnoticed generator progress, but stronger information perks answer bigger questions.","publicationStatus":"published","tags":["Regression"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Leon S. Kennedy"},"synergyPerkIds":["deja-vu","poised","alert","better-together"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Déjà Vu","Poised","Alert","Better Together"],"antiSynergies":[],"name":"Rookie Spirit","alternateName":null,"source":"Leon S. Kennedy","status":"Live 10.2.0","currentEffect":"While repairing Generators, succeed at 5/4/3 Good or Great Skill Checks to activate Rookie Spirit for the remainder of the Trial. It reveals the Auras of any regressing Generators until they stop regressing by any means.","activation":["While repairing Generators, succeed at 5/4/3 Good or Great Skill Checks.","Ends/deactivates when: Each Generator Aura stops being revealed when that Generator stops regressing by any means."],"patchNote":"Latest live balance change (unknown): No material live balance change could be verified from available patch history.","plainEnglishSummary":"After enough successful Generator Skill Checks, you see regressing Generator Auras for the rest of the Trial.","cooldown":null,"duration":["Perk activates for the remainder of the Trial; each Aura reveal lasts while that Generator is regressing."],"tokenOrStackBehavior":"Successful Good or Great Repair Skill Checks count toward the 5/4/3 activation requirement.","oncePerTrialOrOtherLimits":"Activates for the remainder of the Trial after meeting the Skill Check requirement.","statusEffectsInvolved":[],"specialInteractions":[],"sourceCharacter":"Leon S. Kennedy","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"deadline","rank":171,"tier":"D","roles":["Skill Check","Healing","Objective"],"summary":"While injured, Skill Checks occur more often and at random screen positions during repair and healing; failed checks lose 50% less progress.","metaStatus":"Weak","skillLevel":"High","soloQ":1,"swf":1,"unlockPriority":"Low–Medium","glossaryKeys":["health-state","pressure"],"useCases":["Generate more Skill Checks for Hyperfocus, Autodidact, or other check-based builds while injured.","Use the reduced miss penalty to make deliberately difficult Skill Check setups less punishing.","Increase Skill Check opportunities during both generator repair and healing."],"counters":["Only active while Injured.","Random Skill Check positions make execution harder.","More Skill Checks can be a downside if the build gains nothing from them."],"pros":["Unique way to increase Skill Check frequency.","Works on both repairing and healing.","Reduces punishment from failures."],"cons":["Actively increases mechanical difficulty.","Requires staying injured.","Mostly a synergy engine rather than standalone power."],"analysis":["Deadline closes this batch because increasing Skill Check frequency is valuable only when the build has a reason to want extra Skill Checks. Hyperfocus and Autodidact are the clearest examples, turning more checks into more opportunities for their own effects.","The perk deliberately makes those checks less comfortable by moving them to random positions. That raises the execution requirement and can cause more mistakes, though the fifty-percent reduction to missed-check progress loss softens the punishment.","Staying injured is another cost. The perk is inactive while Healthy, so a build that heals frequently may spend much of the Trial without its main effect.","Deadline is therefore a niche engine for people intentionally building around Skill Checks. In that context it can improve consistency through volume; outside that context it is mostly making the HUD more chaotic for no reward."],"verdict":"A specialist Skill Check accelerator. Deadline is useful when your other perks profit from extra checks and unnecessary turbulence everywhere else.","publicationStatus":"published","tags":[],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Alan Wake"},"synergyPerkIds":["hyperfocus","autodidact","this-is-not-happening"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Hyperfocus","Autodidact","This Is Not Happening"],"antiSynergies":[],"name":"Deadline","alternateName":null,"source":"Alan Wake","status":"Live 10.2.0","currentEffect":"While injured, the chance of Skill Checks increases by 6/8/10% while repairing or healing. Skill Checks appear at random positions, and missed-check progress loss is reduced by 50%.","activation":["Be injured.","Repair a Generator or heal while injured.","Ends/deactivates when: Effects are inactive when no longer injured or when not repairing/healing."],"patchNote":"Latest live balance change (unknown): No material live balance change could be verified from available patch history.","plainEnglishSummary":"When injured, you get more frequent, randomly positioned Skill Checks and lose less progress for missing one.","cooldown":null,"duration":["While injured during repair or healing."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":["Skill Check positions are random."],"sourceCharacter":"Alan Wake","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"this-is-not-happening","rank":172,"tier":"D","roles":["Skill Check","Utility"],"summary":"Make Good basic Skill Check zones 150/175/200% larger at all health states.","metaStatus":"Weak","skillLevel":"Low","soloQ":2,"swf":2,"unlockPriority":"Low","glossaryKeys":[],"useCases":["Make ordinary Skill Checks far easier for a new or accessibility-focused player.","Reduce missed checks on unfamiliar interactions.","Use as a temporary learning perk while basic Skill Check consistency develops."],"counters":["It provides no extra progress for hitting a Good check.","The 10.2 live version does not enlarge Great zones.","Experienced players gain almost nothing from the larger Good zone."],"pros":["Works at every health state after 10.2.","Enormous Good-zone increase.","Simple accessibility value."],"cons":["No speed or progress bonus.","No Great-check synergy.","Quickly outgrown by experienced players."],"analysis":["This Is Not Happening is now an accessibility perk rather than an injured-state Great-check perk. Good basic Skill Check zones become enormous, and the health-state requirement is gone.","The live release deliberately removed the PTB Great-zone bonus because of its Hyperfocus interaction. That means experienced players do not receive a progression ceiling from the rework; they simply receive safer ordinary checks.","For new players or anyone who struggles with Skill Check timing, that safety can be useful. Preventing repeated failed checks is real value even if it does not appear on a meta spreadsheet.","Competitive ranking remains low because the perk does not make successful actions faster or more rewarding. It makes failure less likely, which is valuable until the player no longer needs the help."],"verdict":"A pure accessibility and beginner perk in 10.2. Excellent at making Good checks easy, intentionally useless for Great-check optimization.","publicationStatus":"published","reviewFlags":["10.2-live-change","v15-schema-migrated","queue-rating:audit-explicit"],"tags":["Accessibility","Beginner"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"stable","acquisition":{"type":"general","sourceCharacter":"General"},"synergyPerkIds":["corrective-action","technician"],"synergyOther":["Beginner builds"],"antiSynergyPerkIds":[],"archetypeRatings":[],"synergies":["Corrective Action","Technician","Beginner builds"],"antiSynergies":[],"name":"This Is Not Happening","alternateName":null,"source":"General perk","status":"Live 10.2.0","currentEffect":"Good basic Skill Check zones are 150/175/200% bigger.","activation":["Perform an interaction that produces a basic Skill Check with a Good zone."],"patchNote":"Latest live balance change (10.2.0): Complete rework: removed the Injured requirement and old Great Skill Check zone bonus; Good basic Skill Check zones are now 150/175/200% bigger.","plainEnglishSummary":"Greatly enlarges Good basic Skill Check zones.","cooldown":null,"duration":[],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":["Only Good basic Skill Check zones are enlarged in the final live version."],"sourceCharacter":"General","isGeneralPerk":true,"currentLivePatchVerified":"10.2.0"},{"id":"left-behind","rank":173,"tier":"D","roles":["Endgame","Information"],"summary":"When you are the last Survivor remaining, see the Hatch Aura within up to 32 metres.","metaStatus":"Weak","skillLevel":"Low","soloQ":2,"swf":1,"unlockPriority":"Low","glossaryKeys":["aura-reading"],"useCases":["Locate a nearby open Hatch quickly after becoming the last Survivor.","Reduce endgame wandering on indoor maps.","Pair with other last-Survivor tools for a dedicated escape fallback."],"counters":["Does nothing until every teammate is dead or gone.","Only reveals the Hatch within 32 metres.","A perk that helps after team collapse cannot help prevent that collapse."],"pros":["Simple Hatch information.","Can save a desperate final escape.","No setup once the condition is met."],"cons":["Dead for almost the entire Trial.","Selfish endgame-only value.","Short enough range that the Hatch may still require searching."],"analysis":["Left Behind is mechanically clear and strategically bleak: once you are alone, it helps find the Hatch. That can absolutely turn a final 1v1 search into an escape if the Hatch spawns nearby.","The issue is opportunity cost. One of four perk slots contributes nothing while the team is still alive, meaning it does not help create the circumstances in which several Survivors escape together.","The thirty-two-metre limit also means it is guidance rather than a global Hatch reveal. Indoor maps can still require substantial movement before the Aura appears.","Dedicated escape challenges may justify it, but general ranking must punish a perk that only matters after the team has already lost most of its structure."],"verdict":"Good at finding Hatch, bad at everything required before Hatch matters. Left Behind is a last-person fallback, not a team survival perk.","publicationStatus":"published","tags":["Last Survivor","Hatch"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"William \"Bill\" Overbeck"},"synergyPerkIds":["down-to-the-last","clairvoyance","wake-up"],"synergyOther":["Sole-survivor strategies"],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Down to the Last","Clairvoyance","Wake Up!","Sole-survivor strategies"],"antiSynergies":[],"name":"Left Behind","alternateName":null,"source":"William \"Bill\" Overbeck","status":"Live 10.2.0","currentEffect":"When you are the last Survivor remaining in the Trial, the Hatch's Aura is revealed to you within 24/28/32 m.","activation":["Be the last Survivor remaining in the Trial.","Ends/deactivates when: The effect ends when the Trial ends or you are no longer the last Survivor remaining."],"patchNote":"Latest live balance change (3.2.0): Reworked the perk to reveal the Hatch's Aura within 24/28/32 m when you are the last Survivor alive.","plainEnglishSummary":"As the last Survivor remaining, you can see the Hatch's Aura within the tier's range.","cooldown":null,"duration":["While you are the last Survivor remaining; Aura reveal is range-limited."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":[],"sourceCharacter":"William \"Bill\" Overbeck","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"red-herring","rank":174,"tier":"D","roles":["Stealth","Locker","Utility"],"summary":"Briefly repair a Generator to mark it, then enter a Locker to send the Killer a fake Loud Noise notification at that Generator.","metaStatus":"Weak","skillLevel":"High","soloQ":1,"swf":2,"unlockPriority":"Low","glossaryKeys":[],"useCases":["Fake a missed Skill Check on a Generator far from the team’s real pressure.","Pair with a Locker perk so the activation is not a pure detour.","Try to pull a high-mobility Killer toward an irrelevant objective after they finish another task."],"counters":["The Killer may ignore the notification or recognize the bait.","Activating requires leaving productive work and entering a Locker.","A fake notification on an important Generator may accidentally encourage the Killer to defend it."],"pros":["Short 15-second Tier III cooldown.","Can create a remote notification at a chosen Generator.","Some synergy with Locker-focused builds."],"cons":["Opponent-controlled payoff.","Activation costs objective tempo.","Can actively attract the Killer to a Generator you care about."],"analysis":["Red Herring offers a remote fake notification, which sounds strategically flexible until the cost is counted. You must first mark a Generator, leave it, find a Locker, and trust the Killer to believe the resulting noise matters.","The best-case use is sending a mobile Killer toward a generator that is strategically irrelevant while the team pressures elsewhere. That requires timing, map awareness, and an opponent willing to react.","The downside is comical when the marked generator is actually important. A successful bait can bring the Killer directly to progress the team hoped to preserve.","Red Herring remains near the bottom because every layer of value depends on the Killer making the mistake you hoped for. It can be hilarious and still be bad."],"verdict":"A remote decoy with too many chores and too much opponent agency. Red Herring is a fun lie that often costs more time to tell than the Killer loses believing it.","publicationStatus":"published","tags":["Misdirection"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Zarina Kassir"},"synergyPerkIds":["diversion","lucky-star","head-on","deception"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Diversion","Lucky Star","Head On","Deception"],"antiSynergies":[],"name":"Red Herring","alternateName":null,"source":"Zarina Kassir","status":"Live 10.2.0","currentEffect":"After repairing a Generator for at least 1 second, its Aura is highlighted yellow to you. The highlight ends if the Generator is completed, you start repairing another Generator, or you enter a Locker. Entering a Locker while a Generator is highlighted causes a Loud Noise Notification for the Killer at that Generator. Red Herring then has a 25/20/15-second cooldown by tier.","activation":["Repair a Generator for at least 1 second to highlight it.","Enter a Locker while the Generator is highlighted to trigger the Loud Noise Notification.","Ends/deactivates when: The Generator's Aura highlight ends if the Generator is completed, you begin repairing another Generator, or you enter a Locker.","Ends/deactivates when: The cooldown prevents another activation until it expires."],"patchNote":"Latest live balance change (8.6.0): Reduced the repair requirement from 3 seconds to 1 second and reduced cooldown to 25/20/15 seconds from 30/25/20.","plainEnglishSummary":"Repair a Generator briefly to mark it, then entering a Locker sends the Killer a Loud Noise Notification at the marked Generator.","cooldown":"25/20/15 seconds.","duration":["Generator Aura highlight: until the Generator is completed, you start repairing a different Generator, or you enter a Locker."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":null,"statusEffectsInvolved":[],"specialInteractions":["The Killer receives a Loud Noise Notification at the highlighted Generator when you enter a Locker; the notification does not reveal your Aura."],"sourceCharacter":"Zarina Kassir","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"mirrored-illusion","rank":175,"tier":"D","roles":["Stealth","Utility"],"summary":"After enough Generator repair, create a temporary static decoy beside a Chest, Exit Gate, Generator, or Totem.","metaStatus":"Weak","skillLevel":"Medium","soloQ":1,"swf":2,"unlockPriority":"Low","glossaryKeys":[],"useCases":["Place a distant decoy where the Killer might waste a quick glance or ranged action.","Mask the exact position of a real objective from far away.","Use creative prop placement for occasional mindgames."],"counters":["The illusion looks obviously artificial at close range.","Requires 20% repair before each activation cycle.","The Killer can ignore it without losing anything."],"pros":["Creative and funny mindgame potential.","Can be placed on several prop categories.","Long enough duration for a distant visual fake."],"cons":["Weak visual deception up close.","No guaranteed interaction or slowdown.","Repair setup for a purely psychological effect."],"analysis":["Mirrored Illusion is a visual bluff rather than mechanical power. The decoy can occasionally make a Killer spend attention on the wrong object, particularly from long range or in a rushed rotation.","The problem is fidelity. The illusion is visibly holographic at close range, and experienced Killers have little reason to commit meaningful time to verifying it.","The perk also requires generator contribution before use, which means a productive action is being converted into an effect that may generate zero measurable delay.","That keeps Mirrored Illusion near the bottom. It can create memorable stories and clever clips without offering enough repeatable match value for a serious ranking."],"verdict":"Great theater, weak economics. Mirrored Illusion can fool attention for a moment, but rarely fools the Killer long enough to justify the slot.","publicationStatus":"published","tags":["Misdirection","Gimmick"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Aestri Yazar"},"synergyPerkIds":["diversion","red-herring","deception","blast-mine"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Diversion","Red Herring","Deception","Blast Mine"],"antiSynergies":[],"name":"Mirrored Illusion","alternateName":null,"source":"Aestri Yazar","status":"Live 10.2.0","currentEffect":"After you have repaired Generators for a total of 20% progression, press the Active Ability button while next to a Chest, Exit Gate, Generator, or Totem to create a Static Illusion of that prop. The illusion lasts for the tier duration. The perk deactivates after successfully creating an illusion.","activation":["Repair Generators for 20% total progression.","Be next to a Chest, Exit Gate, Generator, or Totem and press the Active Ability button.","Ends/deactivates when: Deactivates after successfully triggering the illusion."],"patchNote":"Latest live balance change (8.2.0): Reduced required Generator repair progression from 50% to 20% and reduced illusion duration from 100/110/120 to 40/50/60 seconds.","plainEnglishSummary":"After repairing 20% total generator progress, you can create a temporary static decoy beside a listed prop.","cooldown":null,"duration":["Static Illusion: 40/50/60 seconds."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":"No explicit once-per-Trial limit is stated; the perk deactivates after a successful trigger and requires its activation condition again to be available for another use.","statusEffectsInvolved":[],"specialInteractions":[],"sourceCharacter":"Aestri Yazar","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"},{"id":"invocation-treacherous-crows","rank":176,"tier":"D","roles":["Invocation","Information"],"summary":"Spend a Basement Invocation to reveal the Killer for up to 2 seconds when they scare Crows near Survivors in their Terror Radius, then remain Broken for the rest of the Trial.","metaStatus":"Weak","skillLevel":"Medium","soloQ":1,"swf":2,"unlockPriority":"Low","glossaryKeys":["broken","aura-reading","terror-radius"],"useCases":["Create global intermittent Killer Aura pings if the Killer frequently scares Crows near Survivors.","Combine with another Invocation user so the Basement ritual completes faster.","Run only in a dedicated challenge or experimental Invocation build."],"counters":["The ritual costs up to 60 seconds in the Basement plus travel time.","The invoker becomes permanently Broken.","The Killer Aura read lasts only 1/1.5/2 seconds and requires a Crow trigger near a Survivor in the Terror Radius."],"pros":["Potential teamwide Killer information.","Other Survivors can accelerate the ritual.","Effect persists after completion."],"cons":["Permanent Broken cost.","Huge setup time.","Tiny, conditional Aura payoff."],"analysis":["Invocation: Treacherous Crows remains the clearest candidate for the bottom of the Survivor list. It charges the same enormous Invocation price as stronger rituals: Basement travel, up to sixty seconds of setup, and permanent Broken afterward.","The reward is only a brief Killer Aura reveal when the Killer scares a Crow while a Survivor is inside the Killer’s Terror Radius. That condition is not fully controlled by the team, and the Tier III read lasts only two seconds.","The information can occasionally help everyone understand Killer location, but the effect is far too small to repay the invoker’s lost health state and objective time in ordinary matches.","Even Invocation synergy does not rescue the economy. The perk is usable for experimentation and challenge builds, but the opportunity cost is so extreme that almost any conventional information perk is healthier for the team."],"verdict":"The cellar door. Treacherous Crows asks for Basement ritual time and permanent Broken in exchange for conditional two-second Aura pings. The math is cruel.","publicationStatus":"published","tags":["Aura Reading","Global"],"queueRatingStatus":"reviewed","rankRange":null,"rankConfidence":"Not assessed","rankStatus":"inherited","evidenceStatus":"inherited","acquisition":{"type":"character","sourceCharacter":"Taurie Cain"},"synergyPerkIds":["invocation-weaving-spiders","resilience","no-mither","eyes-of-belmont"],"synergyOther":[],"antiSynergyPerkIds":[],"archetypeRatings":[],"reviewFlags":["v15-schema-migrated","queue-rating:normalized-tier-plus-v14-specialization-signal"],"synergies":["Invocation: Weaving Spiders","Resilience","No Mither","Eyes of Belmont"],"antiSynergies":[],"name":"Invocation: Treacherous Crows","alternateName":null,"source":"Taurie Cain","status":"Live 10.2.0","currentEffect":"While in the Basement near the Invocation circle, press Activate Ability 2 to begin a 60-second ritual. Your Aura is revealed to all other Survivors during it. Other Survivors can join; each joining Survivor increases ritual speed by 100% if they have an Invocation perk equipped, or 50% otherwise. When completed, whenever the Killer scares a Crow while any Survivor is inside the Killer's Terror Radius, the Killer's Aura is revealed to all Survivors for 1/1.5/2 seconds. Completion puts you into the Injured State and applies Broken to you for the rest of the Trial, and disables other copies of this Invocation for all Survivors for the rest of the Trial.","activation":["Be in the Basement near the Invocation circle and press Activate Ability 2.","Complete the 60-second ritual; teammates may join to increase its speed.","For the post-ritual Aura reveal, the Killer must scare a Crow while at least one Survivor is inside the Killer's Terror Radius.","Ends/deactivates when: The invocation ability is disabled for all Survivors after one completion for the remainder of the Trial.","Ends/deactivates when: The Broken Status Effect on the invoker lasts for the remainder of the Trial."],"patchNote":"Latest live balance change (unknown): No material live balance change could be verified from available patch history.","plainEnglishSummary":"Complete a Basement ritual to reveal the Killer when they scare a Crow near a Survivor, at the cost of becoming Injured and Broken for the Trial.","cooldown":null,"duration":["Ritual: 60 seconds before helper speed modifiers.","Killer Aura reveal: 1/1.5/2 seconds per qualifying Crow event.","Broken: remainder of the Trial."],"tokenOrStackBehavior":null,"oncePerTrialOrOtherLimits":"Each Invocation: Treacherous Crows can be completed once per Trial across all Survivors; completion disables other copies of this Invocation.","statusEffectsInvolved":["Broken"],"specialInteractions":["During an Invocation, teammates can join and speed it up; those with any Invocation perk contribute +100% speed, while those without contribute +50%."],"sourceCharacter":"Taurie Cain","isGeneralPerk":false,"currentLivePatchVerified":"10.2.0"}]);
